{
  "name": "SmartPOS Minimarket",
  "description": "A high-performance, easy-to-use Point of Sales system designed for modern minimarkets, featuring barcode-based scanning, real-time inventory tracking, and multi-payment support.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Category {
  KITCHEN = 'Kebutuhan Dapur',
  SCHOOL = 'Perlengkapan Sekolah',
  HOUSEHOLD = 'Kebutuhan Rumah Tangga',
  FOOD = 'Makanan',
  BEVERAGE = 'Minuman'
}

export enum PaymentMethod {
  CASH = 'Tunai',
  QRIS = 'QRIS',
  DEBIT = 'Debit',
  EWALLET = 'E-Wallet'
}

export interface Product {
  id: string;
  barcode: string;
  name: string;
  category: Category;
  price: number;
  stock: number;
  image?: string;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface Transaction {
  id: string;
  timestamp: Date;
  items: CartItem[];
  subtotal: number;
  tax: number;
  discount: number;
  total: number;
  paymentMethod: PaymentMethod;
  amountPaid: number;
  change: number;
}

import React, { useState, useEffect, useRef } from 'react';
import { Product, CartItem, Category, Transaction, PaymentMethod } from './types';
import { INITIAL_PRODUCTS, TAX_RATE } from './constants';
import { POSView } from './components/POSView';
import { InventoryView } from './components/InventoryView';
import { HistoryView } from './components/HistoryView';
import { Receipt } from './components/Receipt';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'pos' | 'inventory' | 'history'>('pos');
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);

  // Focus barcode input helper
  const barcodeInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (activeTab === 'pos') {
      barcodeInputRef.current?.focus();
    }
  }, [activeTab, cart]);

  const handleAddToCart = (product: Product) => {
    if (product.stock <= 0) {
      alert("Stok habis!");
      return;
    }
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) {
          alert("Maksimal stok tercapai");
          return prev;
        }
        return prev.map(item => 
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const handleRemoveFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const handleUpdateQuantity = (productId: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === productId) {
        const newQty = item.quantity + delta;
        const prod = products.find(p => p.id === productId);
        if (prod && newQty > 0 && newQty <= prod.stock) {
          return { ...item, quantity: newQty };
        }
      }
      return item;
    }));
  };

  const handleCheckout = (paymentMethod: PaymentMethod, amountPaid: number, discount: number = 0) => {
    const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const tax = subtotal * TAX_RATE;
    const total = subtotal + tax - discount;
    const change = amountPaid - total;

    const newTransaction: Transaction = {
      id: `TRX-${Date.now()}`,
      timestamp: new Date(),
      items: [...cart],
      subtotal,
      tax,
      discount,
      total,
      paymentMethod,
      amountPaid,
      change
    };

    // Update stocks
    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(ci => ci.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    setTransactions(prev => [newTransaction, ...prev]);
    setLastTransaction(newTransaction);
    setCart([]);
    setIsReceiptOpen(true);
  };

  return (
    <div className="flex h-screen overflow-hidden">
      {/* Sidebar */}
      <aside className="w-20 md:w-64 bg-slate-900 text-white flex flex-col no-print">
        <div className="p-6 font-bold text-xl hidden md:block">
          Smart<span className="text-emerald-400">POS</span>
        </div>
        <div className="p-4 md:hidden text-center font-bold text-emerald-400">POS</div>

        <nav className="flex-1 mt-6">
          <button 
            onClick={() => setActiveTab('pos')}
            className={`w-full p-4 flex items-center space-x-4 transition-colors ${activeTab === 'pos' ? 'bg-slate-800 border-r-4 border-emerald-400' : 'hover:bg-slate-800'}`}
          >
            <span className="text-xl">🛒</span>
            <span className="hidden md:block">Penjualan</span>
          </button>
          <button 
            onClick={() => setActiveTab('inventory')}
            className={`w-full p-4 flex items-center space-x-4 transition-colors ${activeTab === 'inventory' ? 'bg-slate-800 border-r-4 border-emerald-400' : 'hover:bg-slate-800'}`}
          >
            <span className="text-xl">📦</span>
            <span className="hidden md:block">Inventaris</span>
          </button>
          <button 
            onClick={() => setActiveTab('history')}
            className={`w-full p-4 flex items-center space-x-4 transition-colors ${activeTab === 'history' ? 'bg-slate-800 border-r-4 border-emerald-400' : 'hover:bg-slate-800'}`}
          >
            <span className="text-xl">📜</span>
            <span className="hidden md:block">Riwayat</span>
          </button>
        </nav>

        <div className="p-4 text-xs text-slate-500 hidden md:block border-t border-slate-800">
          V 1.0.2 • Made with ❤️ for Minimarkets
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col bg-slate-50 overflow-hidden no-print">
        <header className="bg-white h-16 border-b border-slate-200 flex items-center justify-between px-6">
          <h1 className="text-xl font-semibold capitalize">{activeTab} Interface</h1>
          <div className="flex items-center space-x-4">
            <span className="bg-emerald-100 text-emerald-700 px-3 py-1 rounded-full text-sm font-medium">Kasir 01</span>
            <div className="w-8 h-8 rounded-full bg-slate-200"></div>
          </div>
        </header>

        <div className="flex-1 overflow-auto">
          {activeTab === 'pos' && (
            <POSView 
              products={products}
              cart={cart}
              onAddToCart={handleAddToCart}
              onRemoveFromCart={handleRemoveFromCart}
              onUpdateQuantity={handleUpdateQuantity}
              onCheckout={handleCheckout}
              barcodeInputRef={barcodeInputRef}
            />
          )}
          {activeTab === 'inventory' && (
            <InventoryView products={products} setProducts={setProducts} />
          )}
          {activeTab === 'history' && (
            <HistoryView transactions={transactions} />
          )}
        </div>
      </main>

      {/* Receipt Modal */}
      {isReceiptOpen && lastTransaction && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 no-print">
          <div className="bg-white rounded-lg shadow-2xl w-full max-w-sm overflow-hidden flex flex-col max-h-[90vh]">
            <div className="flex-1 overflow-auto p-4">
              <Receipt transaction={lastTransaction} />
            </div>
            <div className="p-4 bg-slate-100 flex space-x-3">
              <button 
                onClick={() => window.print()} 
                className="flex-1 bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-3 rounded-lg transition"
              >
                Cetak Struk
              </button>
              <button 
                onClick={() => setIsReceiptOpen(false)} 
                className="flex-1 bg-slate-200 hover:bg-slate-300 text-slate-800 font-bold py-3 rounded-lg transition"
              >
                Tutup
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Hidden Receipt for direct printing */}
      {isReceiptOpen && lastTransaction && (
        <div className="print-only">
          <Receipt transaction={lastTransaction} />
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, Category, PaymentMethod } from '../types';
import { TAX_RATE } from '../constants';

interface POSViewProps {
  products: Product[];
  cart: CartItem[];
  onAddToCart: (product: Product) => void;
  onRemoveFromCart: (productId: string) => void;
  onUpdateQuantity: (productId: string, delta: number) => void;
  onCheckout: (paymentMethod: PaymentMethod, amountPaid: number, discount: number) => void;
  barcodeInputRef: React.RefObject<HTMLInputElement>;
}

export const POSView: React.FC<POSViewProps> = ({ 
  products, 
  cart, 
  onAddToCart, 
  onRemoveFromCart, 
  onUpdateQuantity, 
  onCheckout,
  barcodeInputRef
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState<Category | 'All'>('All');
  const [paymentAmount, setPaymentAmount] = useState<string>('');
  const [discount, setDiscount] = useState<string>('0');
  const [selectedPayment, setSelectedPayment] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckoutModal, setShowCheckoutModal] = useState(false);

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const tax = subtotal * TAX_RATE;
  const total = subtotal + tax - (parseFloat(discount) || 0);

  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.barcode.includes(searchTerm);
    const matchesCategory = activeCategory === 'All' || p.category === activeCategory;
    return matchesSearch && matchesCategory;
  });

  const handleBarcodeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product = products.find(p => p.barcode === searchTerm);
    if (product) {
      onAddToCart(product);
      setSearchTerm('');
    } else {
      // If not barcode, might be search, so just keep focus
    }
  };

  const handleProcessPayment = () => {
    const paid = parseFloat(paymentAmount);
    if (paid < total) {
      alert("Pembayaran kurang!");
      return;
    }
    onCheckout(selectedPayment, paid, parseFloat(discount) || 0);
    setShowCheckoutModal(false);
    setPaymentAmount('');
    setDiscount('0');
  };

  return (
    <div className="flex h-full p-6 space-x-6 overflow-hidden">
      {/* Left Column: Product Selection */}
      <div className="flex-1 flex flex-col space-y-4">
        {/* Search & Barcode */}
        <div className="bg-white p-4 rounded-xl shadow-sm flex items-center space-x-4 border border-slate-200">
          <form onSubmit={handleBarcodeSubmit} className="flex-1 relative">
            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">🔍</span>
            <input 
              ref={barcodeInputRef}
              type="text" 
              placeholder="Cari produk atau scan barcode..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-slate-100 rounded-lg outline-none focus:ring-2 focus:ring-emerald-400"
            />
          </form>
          <div className="flex space-x-2">
            <button 
              onClick={() => setActiveCategory('All')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition ${activeCategory === 'All' ? 'bg-emerald-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
            >
              Semua
            </button>
            {Object.values(Category).map(cat => (
              <button 
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition whitespace-nowrap ${activeCategory === cat ? 'bg-emerald-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        {/* Product Grid */}
        <div className="flex-1 overflow-y-auto grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 pb-6">
          {filteredProducts.map(product => (
            <button 
              key={product.id}
              onClick={() => onAddToCart(product)}
              className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 hover:border-emerald-400 hover:shadow-md transition text-left group flex flex-col h-full"
            >
              <div className="w-full aspect-square bg-slate-50 rounded-lg mb-3 flex items-center justify-center text-4xl group-hover:scale-105 transition-transform">
                {product.category === Category.FOOD ? '🍔' : 
                 product.category === Category.BEVERAGE ? '🥤' : 
                 product.category === Category.KITCHEN ? '🍳' : 
                 product.category === Category.SCHOOL ? '✏️' : '🏠'}
              </div>
              <h3 className="font-semibold text-slate-800 line-clamp-2 flex-1">{product.name}</h3>
              <div className="mt-2 flex justify-between items-end">
                <div>
                  <p className="text-xs text-slate-500">{product.barcode}</p>
                  <p className="font-bold text-emerald-600">Rp {product.price.toLocaleString()}</p>
                </div>
                <div className={`text-xs px-2 py-1 rounded-full ${product.stock < 10 ? 'bg-orange-100 text-orange-600' : 'bg-slate-100 text-slate-500'}`}>
                  Stok: {product.stock}
                </div>
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Right Column: Cart & Checkout */}
      <div className="w-96 flex flex-col bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
        <div className="p-4 bg-slate-50 border-b border-slate-200">
          <h2 className="font-bold flex items-center justify-between">
            <span>Daftar Belanja</span>
            <span className="bg-slate-200 px-2 py-0.5 rounded text-sm text-slate-600">{cart.length} item</span>
          </h2>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {cart.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-slate-400 space-y-2">
              <span className="text-4xl">🛒</span>
              <p>Keranjang masih kosong</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex space-x-3 items-start p-2 hover:bg-slate-50 rounded-lg transition group">
                <div className="flex-1">
                  <h4 className="font-medium text-sm text-slate-800">{item.name}</h4>
                  <p className="text-xs text-slate-500">Rp {item.price.toLocaleString()}</p>
                </div>
                <div className="flex items-center space-x-2">
                  <button onClick={() => onUpdateQuantity(item.id, -1)} className="w-6 h-6 rounded-full bg-slate-200 flex items-center justify-center hover:bg-slate-300">-</button>
                  <span className="text-sm font-bold w-6 text-center">{item.quantity}</span>
                  <button onClick={() => onUpdateQuantity(item.id, 1)} className="w-6 h-6 rounded-full bg-slate-200 flex items-center justify-center hover:bg-slate-300">+</button>
                  <button onClick={() => onRemoveFromCart(item.id)} className="ml-2 text-slate-300 hover:text-red-500 transition">✕</button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-4 bg-slate-50 border-t border-slate-200 space-y-2">
          <div className="flex justify-between text-slate-600">
            <span>Subtotal</span>
            <span>Rp {subtotal.toLocaleString()}</span>
          </div>
          <div className="flex justify-between text-slate-600">
            <span>Pajak (11%)</span>
            <span>Rp {tax.toLocaleString()}</span>
          </div>
          <div className="flex justify-between items-center text-slate-600">
            <span>Diskon</span>
            <input 
              type="number" 
              value={discount} 
              onChange={(e) => setDiscount(e.target.value)}
              className="w-24 text-right px-2 py-1 bg-white border border-slate-200 rounded text-sm outline-none focus:ring-1 focus:ring-emerald-400"
            />
          </div>
          <div className="flex justify-between font-bold text-xl text-slate-900 pt-2 border-t border-slate-200">
            <span>Total</span>
            <span className="text-emerald-600">Rp {total.toLocaleString()}</span>
          </div>
          <button 
            disabled={cart.length === 0}
            onClick={() => {
              setPaymentAmount(total.toString());
              setShowCheckoutModal(true);
            }}
            className={`w-full py-4 rounded-xl font-bold text-white shadow-lg transition mt-4 ${cart.length === 0 ? 'bg-slate-300 cursor-not-allowed' : 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200'}`}
          >
            BAYAR SEKARANG
          </button>
        </div>
      </div>

      {/* Checkout Modal */}
      {showCheckoutModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[60] p-4">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <h2 className="text-2xl font-bold text-slate-800">Pembayaran</h2>
              <button onClick={() => setShowCheckoutModal(false)} className="text-slate-400 hover:text-slate-600 text-2xl">✕</button>
            </div>

            <div className="p-6 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                {Object.values(PaymentMethod).map(method => (
                  <button 
                    key={method}
                    onClick={() => setSelectedPayment(method)}
                    className={`p-4 border-2 rounded-xl flex flex-col items-center transition ${selectedPayment === method ? 'border-emerald-500 bg-emerald-50 text-emerald-700' : 'border-slate-100 hover:border-slate-200 text-slate-600'}`}
                  >
                    <span className="text-3xl mb-1">
                      {method === PaymentMethod.CASH ? '💵' : 
                       method === PaymentMethod.QRIS ? '📱' : 
                       method === PaymentMethod.DEBIT ? '💳' : '👛'}
                    </span>
                    <span className="font-semibold">{method}</span>
                  </button>
                ))}
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-500 mb-2">Total Belanja</label>
                <div className="text-4xl font-black text-slate-900">Rp {total.toLocaleString()}</div>
              </div>

              {selectedPayment === PaymentMethod.CASH && (
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-500 mb-2">Jumlah Dibayar</label>
                    <input 
                      autoFocus
                      type="number" 
                      value={paymentAmount} 
                      onChange={(e) => setPaymentAmount(e.target.value)}
                      className="w-full text-3xl font-bold px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-emerald-400"
                      placeholder="Masukkan jumlah uang..."
                    />
                  </div>

                  {parseFloat(paymentAmount) >= total && (
                    <div className="p-4 bg-emerald-50 rounded-xl border border-emerald-100 flex justify-between items-center">
                      <span className="text-emerald-700 font-medium">Kembalian</span>
                      <span className="text-2xl font-bold text-emerald-700">Rp {(parseFloat(paymentAmount) - total).toLocaleString()}</span>
                    </div>
                  )}
                </div>
              )}

              {selectedPayment !== PaymentMethod.CASH && (
                <div className="p-4 bg-blue-50 text-blue-700 rounded-xl border border-blue-100 flex items-center space-x-3">
                  <span className="text-xl">ℹ️</span>
                  <p className="text-sm font-medium">Silakan arahkan pelanggan untuk melakukan scan pada terminal EDC atau QRIS.</p>
                </div>
              )}
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-100">
              <button 
                onClick={handleProcessPayment}
                className="w-full py-4 bg-emerald-600 hover:bg-emerald-700 text-white text-xl font-bold rounded-xl shadow-lg shadow-emerald-200 transition"
              >
                KONFIRMASI PEMBAYARAN
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Product, Category } from '../types';

interface InventoryViewProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
}

export const InventoryView: React.FC<InventoryViewProps> = ({ products, setProducts }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    barcode: '',
    category: Category.FOOD,
    price: 0,
    stock: 0
  });

  const handleSave = () => {
    if (!formData.name || !formData.barcode || !formData.price) {
      alert("Harap lengkapi semua data!");
      return;
    }

    if (editingId) {
      setProducts(prev => prev.map(p => p.id === editingId ? { ...p, ...formData } as Product : p));
      setEditingId(null);
    } else {
      const newProduct: Product = {
        ...formData,
        id: Date.now().toString(),
      } as Product;
      setProducts(prev => [...prev, newProduct]);
      setIsAdding(false);
    }
    setFormData({ name: '', barcode: '', category: Category.FOOD, price: 0, stock: 0 });
  };

  const handleEdit = (p: Product) => {
    setFormData(p);
    setEditingId(p.id);
    setIsAdding(true);
  };

  const handleDelete = (id: string) => {
    if (confirm("Hapus produk ini?")) {
      setProducts(prev => prev.filter(p => p.id !== id));
    }
  };

  return (
    <div className="p-6 h-full flex flex-col space-y-6 overflow-hidden">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-slate-800">Manajemen Inventaris</h2>
        <button 
          onClick={() => {
            setIsAdding(true);
            setEditingId(null);
            setFormData({ name: '', barcode: '', category: Category.FOOD, price: 0, stock: 0 });
          }}
          className="bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-2 rounded-lg font-bold transition flex items-center space-x-2"
        >
          <span>➕</span>
          <span>Tambah Produk</span>
        </button>
      </div>

      <div className="flex-1 overflow-auto bg-white rounded-xl shadow-sm border border-slate-200">
        <table className="w-full text-left">
          <thead className="bg-slate-50 sticky top-0 border-b border-slate-200">
            <tr>
              <th className="p-4 font-semibold text-slate-600">Barcode</th>
              <th className="p-4 font-semibold text-slate-600">Nama Produk</th>
              <th className="p-4 font-semibold text-slate-600">Kategori</th>
              <th className="p-4 font-semibold text-slate-600">Harga</th>
              <th className="p-4 font-semibold text-slate-600">Stok</th>
              <th className="p-4 font-semibold text-slate-600">Aksi</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {products.map(product => (
              <tr key={product.id} className="hover:bg-slate-50 transition">
                <td className="p-4 font-mono text-sm text-slate-500">{product.barcode}</td>
                <td className="p-4 font-medium text-slate-800">{product.name}</td>
                <td className="p-4">
                  <span className="bg-slate-100 text-slate-600 text-xs px-2 py-1 rounded-full">{product.category}</span>
                </td>
