      {/* Checkout Modal */}
      {showCheckoutModal && (
        <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-[110] p-4 backdrop-blur-md">
          <div className="bg-slate-900 border border-white/10 rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col animate-in fade-in zoom-in duration-300">
            <div className="p-6 border-b border-white/5 flex justify-between items-center">
              <h2 className="text-2xl font-black tracking-tight">PEMBAYARAN</h2>
              <button onClick={() => setShowCheckoutModal(false)} className="text-slate-500 hover:text-white transition-colors text-2xl">✕</button>
            </div>

            <div className="p-8 space-y-8">
              <div className="grid grid-cols-2 gap-4">
                {Object.values(PaymentMethod).map(method => (
                  <button 
                    key={method}
                    onClick={() => setSelectedPayment(method)}
                    className={`p-5 border-2 rounded-2xl flex flex-col items-center gap-2 transition-all ${selectedPayment === method ? 'border-indigo-500 bg-indigo-500/10 text-indigo-400' : 'border-slate-800 hover:border-slate-700 text-slate-500'}`}
                  >
                    <span className="text-3xl">
                      {method === PaymentMethod.CASH ? '💵' : method === PaymentMethod.QRIS ? '📱' : method === PaymentMethod.DEBIT ? '💳' : '👛'}
                    </span>
                    <span className="font-bold text-sm uppercase tracking-widest">{method}</span>
                  </button>
                ))}
              </div>

              <div className="text-center">
                <span className="text-slate-500 text-sm font-bold uppercase tracking-widest">Jumlah Tagihan</span>
                <div className="text-5xl font-black text-white mt-1 tracking-tighter">Rp {total.toLocaleString()}</div>
              </div>

              {selectedPayment === PaymentMethod.CASH && (
                <div className="space-y-4">
                  <div className="relative">
                    <span className="absolute left-4 top-1/2 -translate-y-1/2 text-2xl text-slate-500">Rp</span>
                    <input 
                      autoFocus
                      type="number" 
                      value={paymentAmount} 
                      onChange={(e) => setPaymentAmount(e.target.value)}
                      className="w-full pl-16 pr-6 py-5 bg-slate-950 border border-white/5 rounded-2xl text-3xl font-black outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                      placeholder="0"
                    />
                  </div>

                  {parseFloat(paymentAmount) >= total && (
                    <div className="p-5 bg-indigo-500/10 rounded-2xl border border-indigo-500/20 flex justify-between items-center animate-in slide-in-from-bottom-2">
                      <span className="text-indigo-400 font-bold uppercase tracking-widest text-sm">Kembalian</span>
                      <span className="text-3xl font-black text-indigo-400">Rp {(parseFloat(paymentAmount) - total).toLocaleString()}</span>
                    </div>
                  )}
                </div>
              )}
            </div>

            <div className="p-8 pt-0">
              <button 
                onClick={handleProcessPayment}
                className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white text-xl font-black rounded-2xl shadow-xl shadow-indigo-600/30 transition-all active:scale-[0.98]"
              >
                KONFIRMASI LUNAS
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI } from '@google/genai';
import { Product, Transaction } from '../types';

interface AIAssistantProps {
  onClose: () => void;
  products: Product[];
  transactions: Transaction[];
}

export const AIAssistant: React.FC<AIAssistantProps> = ({ onClose, products, transactions }) => {
  const [messages, setMessages] = useState<{role: 'user' | 'ai', content: string}[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (messages.length === 0) {
      setMessages([{
        role: 'ai',
        content: 'Halo! Saya asisten SmartPOS. Ada yang bisa saya bantu terkait inventaris atau laporan penjualan hari ini?'
      }]);
    }
  }, []);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMessage }]);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const productContext = products.map(p => `- ${p.name} (Barcode: ${p.barcode}, Stok: ${p.stock}, Harga: Rp ${p.price})`).join('\n');
      const salesContext = `Total transaksi hari ini: ${transactions.length}. Total pendapatan: Rp ${transactions.reduce((a,b) => a + b.total, 0).toLocaleString()}`;

      const systemPrompt = `Anda adalah asisten POS minimarket yang cerdas dan efisien. 
      Berikut adalah data toko saat ini:
      PRODUK:
      ${productContext}

      PENJUALAN:
      ${salesContext}

      Gunakan data ini untuk menjawab pertanyaan kasir dengan singkat, sopan, dan profesional. 
      Berikan saran jika stok hampir habis (< 10 unit).`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMessage,
        config: {
          systemInstruction: systemPrompt,
          temperature: 0.7,
        }
      });

      setMessages(prev => [...prev, { role: 'ai', content: response.text || 'Maaf, saya tidak bisa memproses permintaan tersebut.' }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', content: 'Terjadi kesalahan saat menghubungi server AI.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed right-0 top-0 bottom-0 w-96 bg-slate-950 border-l border-white/10 z-[120] flex flex-col shadow-2xl animate-in slide-in-from-right duration-300">
      <div className="p-6 border-b border-white/10 flex items-center justify-between bg-gradient-to-r from-indigo-900/50 to-slate-950">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-indigo-500 flex items-center justify-center">✨</div>
          <h2 className="font-black tracking-tight">SMART AI ASISTEN</h2>
        </div>
        <button onClick={onClose} className="text-slate-500 hover:text-white transition-colors">✕</button>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-4">
        {messages.map((msg, i) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-3 rounded-2xl text-sm ${
              msg.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-tr-none' 
                : 'bg-white/5 border border-white/10 text-slate-300 rounded-tl-none'
            }`}>
              {msg.content}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white/5 border border-white/10 p-4 rounded-2xl flex gap-2">
              <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce"></div>
              <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce delay-100"></div>
              <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce delay-200"></div>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 border-t border-white/10 bg-slate-900/50">
        <div className="flex gap-2">
          <input 
            type="text" 
            placeholder="Tanya stok, saran diskon..." 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            className="flex-1 bg-slate-950 border border-white/10 rounded-xl px-4 py-2.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
          />
          <button 
            onClick={handleSend}
            disabled={isLoading}
            className="bg-indigo-600 hover:bg-indigo-500 p-2.5 rounded-xl transition-all disabled:opacity-50"
          >
            🚀
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Product, Category } from '../types';

interface InventoryViewProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
}

