                    </div>
                  </div>
                </td>
                <td className="p-5">
                  <span className="text-[10px] font-black uppercase tracking-widest px-2.5 py-1 bg-slate-800 text-slate-400 rounded-lg border border-white/5">
                    {product.category}
                  </span>
