            <div className="mt-10 flex gap-4">
              <button onClick={() => setIsAdding(false)} className="flex-1 py-4 bg-slate-800 hover:bg-slate-700 text-slate-400 font-black rounded-2xl transition-all">BATAL</button>
              <button onClick={handleSave} className="flex-1 py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-black rounded-2xl shadow-xl shadow-indigo-600/20 transition-all active:scale-95">SIMPAN</button>
            </div>
