        <div className="p-4 no-print">
          <button 
            onClick={() => setIsAIOpen(true)}
            className="w-full bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 p-3 rounded-xl flex items-center justify-center space-x-2 shadow-lg shadow-indigo-500/20 transition-all active:scale-95"
          >
            <span className="text-xl animate-pulse">✨</span>
            <span className="hidden md:block font-bold">Tanya AI</span>
          </button>
        </div>

        <div className="p-6 border-t border-slate-800">
           <div className="hidden md:flex items-center space-x-3">
              <div className="w-8 h-8 rounded-full bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center text-xs font-bold text-indigo-400">S</div>
              <div className="text-xs">
                <p className="font-bold">Sukron</p>
                <p className="text-slate-500">Admin Mart</p>
              </div>
           </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-16 border-b border-slate-800 flex items-center justify-between px-8 bg-slate-950/50 backdrop-blur-md">
          <div className="flex items-center space-x-4">
            <h1 className="text-lg font-bold uppercase tracking-wider text-slate-400">{activeTab}</h1>
            <div className="h-4 w-[1px] bg-slate-800"></div>
            <div className="text-sm text-slate-500 font-medium">Terminal #001</div>
          </div>
          <div className="flex items-center space-x-6">
            <div className="flex flex-col items-end">
                <span className="text-xs text-slate-500">Hari ini</span>
                <span className="text-sm font-bold">Rp {transactions.reduce((a,b) => a + b.total, 0).toLocaleString()}</span>
            </div>
            <div className="w-10 h-10 rounded-full bg-slate-800 border border-slate-700"></div>
          </div>
        </header>

        <div className="flex-1 overflow-auto bg-[#0f172a] p-4">
          {activeTab === 'pos' && (
            <POSView 
              products={products}
              cart={cart}
              onAddToCart={handleAddToCart}
              onRemoveFromCart={handleRemoveFromCart}
              onUpdateQuantity={handleUpdateQuantity}
              onCheckout={handleCheckout}
              barcodeInputRef={barcodeInputRef}
            />
          )}
          {activeTab === 'inventory' && (
            <InventoryView products={products} setProducts={setProducts} />
          )}
          {activeTab === 'history' && (
            <HistoryView transactions={transactions} />
          )}
        </div>
      </main>

      {/* AI Assistant Side Panel */}
      {isAIOpen && (
        <AIAssistant 
          onClose={() => setIsAIOpen(false)} 
          products={products} 
          transactions={transactions}
        />
      )}

      {/* Receipt Modal */}
      {isReceiptOpen && lastTransaction && (
        <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-[100] p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden flex flex-col max-h-[90vh] scale-in">
            <div className="flex-1 overflow-auto p-4 bg-white">
              <Receipt transaction={lastTransaction} />
            </div>
            <div className="p-4 bg-slate-50 border-t border-slate-100 flex space-x-3">
              <button onClick={() => window.print()} className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl transition">Cetak</button>
              <button onClick={() => setIsReceiptOpen(false)} className="flex-1 bg-slate-200 hover:bg-slate-300 text-slate-800 font-bold py-3 rounded-xl transition">Selesai</button>
            </div>
          </div>
        </div>
      )}

      {/* Direct Printing */}
      {isReceiptOpen && lastTransaction && (
        <div className="print-only">
          <Receipt transaction={lastTransaction} />
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, Category, PaymentMethod } from '../types';
import { TAX_RATE } from '../constants';

interface POSViewProps {
  products: Product[];
  cart: CartItem[];
  onAddToCart: (product: Product) => void;
  onRemoveFromCart: (productId: string) => void;
  onUpdateQuantity: (productId: string, delta: number) => void;
  onCheckout: (paymentMethod: PaymentMethod, amountPaid: number, discount: number, customerName: string) => void;
  barcodeInputRef: React.RefObject<HTMLInputElement>;
}

export const POSView: React.FC<POSViewProps> = ({ 
  products, 
  cart, 
  onAddToCart, 
  onRemoveFromCart, 
  onUpdateQuantity, 
  onCheckout,
  barcodeInputRef
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [customerName, setCustomerName] = useState('');
  const [activeCategory, setActiveCategory] = useState<Category | 'All'>('All');
  const [paymentAmount, setPaymentAmount] = useState<string>('');
  const [discount, setDiscount] = useState<string>('0');
  const [selectedPayment, setSelectedPayment] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckoutModal, setShowCheckoutModal] = useState(false);

  // Focus search input when the internal checkout modal is closed
  useEffect(() => {
    if (!showCheckoutModal) {
      barcodeInputRef.current?.focus();
    }
  }, [showCheckoutModal]);

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const tax = subtotal * TAX_RATE;
  const total = subtotal + tax - (parseFloat(discount) || 0);

  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.barcode.includes(searchTerm);
    const matchesCategory = activeCategory === 'All' || p.category === activeCategory;
    return matchesSearch && matchesCategory;
  });

  const lowStockCount = filteredProducts.filter(p => p.stock > 0 && p.stock < 10).length;

  const handleBarcodeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product = products.find(p => p.barcode === searchTerm);
    if (product) {
      onAddToCart(product);
      setSearchTerm('');
    }
  };

  const handleProcessPayment = () => {
    const paid = parseFloat(paymentAmount);
    if (paid < total) return;
    onCheckout(selectedPayment, paid, parseFloat(discount) || 0, customerName);
    setShowCheckoutModal(false);
    setPaymentAmount('');
    setCustomerName('');
  };

  return (
    <div className="flex h-full gap-4 overflow-hidden">
      <div className="flex-1 flex flex-col gap-4 overflow-hidden">
        {/* Modern Search */}
        <div className="flex items-center gap-3">
          <div className="flex-1 relative">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500">🔍</span>
            <form onSubmit={handleBarcodeSubmit}>
              <input 
                ref={barcodeInputRef}
                type="text" 
                placeholder="Scan barcode atau cari produk..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-12 pr-4 py-3 bg-slate-900 border border-slate-800 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all text-slate-200"
              />
            </form>
          </div>
          <div className="flex gap-2 overflow-x-auto pb-1">
            <button 
              onClick={() => setActiveCategory('All')}
              className={`px-5 py-2.5 rounded-xl text-sm font-semibold transition-all whitespace-nowrap ${activeCategory === 'All' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'bg-slate-900 text-slate-400 hover:text-slate-200 border border-slate-800'}`}
            >
              Semua
            </button>
            {Object.values(Category).map(cat => (
              <button 
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-5 py-2.5 rounded-xl text-sm font-semibold transition-all whitespace-nowrap ${activeCategory === cat ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'bg-slate-900 text-slate-400 hover:text-slate-200 border border-slate-800'}`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        {/* Low Stock Banner Notification */}
        {lowStockCount > 0 && (
          <div className="bg-rose-500/10 border border-rose-500/20 rounded-2xl p-3 flex items-center justify-between animate-in slide-in-from-top duration-300">
            <div className="flex items-center gap-3 text-rose-400">
              <span className="text-xl">⚠️</span>
              <span className="text-sm font-bold">Peringatan: {lowStockCount} produk dalam daftar ini memiliki stok kritis (di bawah 10 unit).</span>
            </div>
          </div>
        )}

        {/* Product List */}
        <div className="flex-1 overflow-y-auto grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4 pr-2">
          {filteredProducts.map(product => {
            const isLowStock = product.stock > 0 && product.stock < 10;
            const isOutOfStock = product.stock === 0;

            return (
              <button 
                key={product.id}
                onClick={() => onAddToCart(product)}
                disabled={isOutOfStock}
                className={`group relative bg-slate-900 border p-4 rounded-2xl transition-all text-left flex flex-col h-full ${
                  isOutOfStock ? 'opacity-50 grayscale cursor-not-allowed border-slate-800' : 
                  isLowStock ? 'border-rose-500/30 bg-rose-500/5 hover:border-rose-500/60' : 'border-slate-800 hover:border-indigo-500/50 hover:bg-slate-800/50'
                }`}
              >
                {isLowStock && (
                  <div className="absolute -top-2 -right-2 bg-rose-500 text-white text-[10px] font-black px-2 py-1 rounded-lg shadow-lg z-10 animate-bounce">
                    STOK TIPIS!
                  </div>
                )}

                <div className={`w-full aspect-square bg-slate-950 rounded-xl mb-4 flex items-center justify-center text-4xl group-hover:scale-105 transition-transform duration-300 ${isLowStock ? 'ring-2 ring-rose-500/20' : ''}`}>
                  {product.category === Category.FOOD ? '🍜' : 
                   product.category === Category.BEVERAGE ? '🥤' : 
                   product.category === Category.KITCHEN ? '🧂' : 
                   product.category === Category.SCHOOL ? '📓' : '🧼'}
                </div>
                <h3 className={`font-bold mb-1 line-clamp-2 text-sm ${isLowStock ? 'text-rose-100' : 'text-slate-200'}`}>{product.name}</h3>
                <p className="text-xs text-slate-500 font-mono mb-3">{product.barcode}</p>
                <div className="mt-auto flex justify-between items-center">
                  <span className={`font-black ${isLowStock ? 'text-rose-400' : 'text-indigo-400'}`}>Rp {product.price.toLocaleString()}</span>
                  <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase ${
                    isOutOfStock ? 'bg-slate-800 text-slate-500' :
                    isLowStock ? 'bg-rose-500/20 text-rose-400 animate-pulse' : 'bg-slate-800 text-slate-500'
                  }`}>
                    {isOutOfStock ? 'HABIS' : `${product.stock} Sisa`}
                  </span>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* Cart Panel */}
      <div className="w-96 glass rounded-3xl flex flex-col overflow-hidden border border-white/5">
        <div className="p-6 border-b border-white/5 flex flex-col gap-4">
          <div className="flex items-center justify-between">
            <h2 className="font-black text-lg tracking-tight">KANTONG BELANJA</h2>
            <span className="bg-indigo-600 text-white text-[10px] font-black px-2 py-1 rounded-md">{cart.length} ITEMS</span>
          </div>

          <div className="relative">
            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 text-xs">👤</span>
            <input 
              type="text" 
              placeholder="Nama Pembeli..." 
              value={customerName}
              onChange={(e) => setCustomerName(e.target.value)}
              className="w-full pl-8 pr-3 py-2 bg-slate-950/50 border border-white/5 rounded-xl text-sm outline-none focus:ring-1 focus:ring-indigo-500 transition-all text-slate-200"
            />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-600 space-y-4">
              <div className="w-20 h-20 rounded-full bg-slate-800/50 flex items-center justify-center text-3xl opacity-50">🛒</div>
              <p className="font-medium">Belum ada barang</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex gap-4 p-3 rounded-2xl bg-white/5 border border-white/5 group hover:bg-white/10 transition-all">
                <div className="flex-1">
                  <h4 className="font-bold text-sm text-slate-200 line-clamp-1">{item.name}</h4>
                  <div className="flex justify-between items-center mt-1">
                    <span className="text-xs text-indigo-400 font-bold">Rp {item.price.toLocaleString()}</span>
                    <div className="flex items-center gap-3">
                        <button onClick={() => onUpdateQuantity(item.id, -1)} className="w-6 h-6 rounded-lg bg-slate-800 flex items-center justify-center text-xs hover:bg-indigo-600 transition-colors">-</button>
                        <span className="text-sm font-black w-4 text-center">{item.quantity}</span>
                        <button onClick={() => onUpdateQuantity(item.id, 1)} className="w-6 h-6 rounded-lg bg-slate-800 flex items-center justify-center text-xs hover:bg-indigo-600 transition-colors">+</button>
                    </div>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-slate-950/50 space-y-4 border-t border-white/5">
          <div className="space-y-2">
            <div className="flex justify-between text-slate-400 text-sm">
              <span>Subtotal</span>
              <span className="font-mono">Rp {subtotal.toLocaleString()}</span>
            </div>
            <div className="flex justify-between text-slate-400 text-sm">
              <span>PPN (11%)</span>
              <span className="font-mono">Rp {tax.toLocaleString()}</span>
            </div>
            <div className="flex justify-between items-center text-slate-400 text-sm">
              <span>Diskon Manual</span>
              <input 
                type="number" 
                value={discount} 
                onChange={(e) => setDiscount(e.target.value)}
                className="w-24 text-right px-2 py-1 bg-slate-900 border border-white/10 rounded-lg text-xs outline-none focus:ring-1 focus:ring-indigo-500"
              />
            </div>
          </div>
          <div className="pt-4 border-t border-white/10 flex justify-between items-end">
            <span className="font-black text-slate-400">TOTAL AKHIR</span>
            <span className="text-3xl font-black text-indigo-400 tracking-tighter">Rp {total.toLocaleString()}</span>
          </div>
          <button 
            disabled={cart.length === 0}
            onClick={() => {
              setPaymentAmount(total.toString());
              setShowCheckoutModal(true);
            }}
            className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-800 disabled:text-slate-500 text-white rounded-2xl font-black text-lg transition-all shadow-xl shadow-indigo-600/20 active:scale-[0.98]"
          >
            BAYAR SEKARANG
          </button>
        </div>
      </div>

      {/* Checkout Modal - Compact Version */}
      {showCheckoutModal && (
        <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-[110] p-4 backdrop-blur-md">
          <div className="bg-slate-900 border border-white/10 rounded-2xl shadow-2xl w-full max-w-md overflow-hidden flex flex-col animate-in fade-in zoom-in duration-200">
            <div className="p-4 border-b border-white/5 flex justify-between items-center">
              <h2 className="text-xl font-black tracking-tight">PEMBAYARAN</h2>
              <button onClick={() => setShowCheckoutModal(false)} className="text-slate-500 hover:text-white transition-colors text-xl">✕</button>
            </div>

            <div className="p-5 space-y-6">
              <div className="flex items-center justify-between p-3 bg-indigo-500/5 rounded-xl border border-indigo-500/10">
                <span className="text-slate-400 text-xs">Pembeli:</span>
                <span className="text-white text-sm font-bold uppercase">{customerName || 'Umum'}</span>
              </div>

              <div className="grid grid-cols-2 gap-3">
                {Object.values(PaymentMethod).map(method => (
                  <button 
                    key={method}
                    onClick={() => setSelectedPayment(method)}
                    className={`p-3 border-2 rounded-xl flex flex-col items-center gap-1 transition-all ${selectedPayment === method ? 'border-indigo-500 bg-indigo-500/10 text-indigo-400' : 'border-slate-800 hover:border-slate-700 text-slate-500'}`}
                  >
                    <span className="text-2xl">
                      {method === PaymentMethod.CASH ? '💵' : method === PaymentMethod.QRIS ? '📱' : method === PaymentMethod.DEBIT ? '💳' : '👛'}
                    </span>
                    <span className="font-bold text-[10px] uppercase tracking-wider">{method}</span>
                  </button>
                ))}
              </div>

              <div className="text-center py-2">
                <span className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">Jumlah Tagihan</span>
                <div className="text-3xl font-black text-white mt-1 tracking-tighter">Rp {total.toLocaleString()}</div>
              </div>

              {selectedPayment === PaymentMethod.CASH && (
                <div className="space-y-3">
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-lg text-slate-500 font-bold">Rp</span>
                    <input 
                      autoFocus
                      type="number" 
                      value={paymentAmount} 
                      onChange={(e) => setPaymentAmount(e.target.value)}
                      className="w-full pl-12 pr-4 py-3 bg-slate-950 border border-white/5 rounded-xl text-2xl font-black outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-white"
                      placeholder="0"
                    />
                  </div>

                  {parseFloat(paymentAmount) >= total && (
                    <div className="p-3 bg-indigo-500/10 rounded-xl border border-indigo-500/20 flex justify-between items-center animate-in slide-in-from-bottom-1">
                      <span className="text-indigo-400 font-bold uppercase tracking-widest text-[10px]">Kembalian</span>
                      <span className="text-xl font-black text-indigo-400">Rp {(parseFloat(paymentAmount) - total).toLocaleString()}</span>
                    </div>
                  )}
                </div>
              )}
            </div>

            <div className="p-5 pt-0">
              <button 
                onClick={handleProcessPayment}
                className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white text-lg font-black rounded-xl shadow-lg shadow-indigo-600/30 transition-all active:scale-[0.98]"
              >
                KONFIRMASI LUNAS
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export enum Category {
  KITCHEN = 'Kebutuhan Dapur',
  SCHOOL = 'Perlengkapan Sekolah',
  HOUSEHOLD = 'Kebutuhan Rumah Tangga',
  FOOD = 'Makanan',
  BEVERAGE = 'Minuman'
}

export enum PaymentMethod {
  CASH = 'Tunai',
  QRIS = 'QRIS',
  DEBIT = 'Debit',
  EWALLET = 'E-Wallet'
}

export interface Product {
  id: string;
  barcode: string;
  name: string;
  category: Category;
  price: number;
  stock: number;
  image?: string;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface Transaction {
  id: string;
  timestamp: Date;
  items: CartItem[];
  subtotal: number;
  tax: number;
  discount: number;
  total: number;
  paymentMethod: PaymentMethod;
  amountPaid: number;
  change: number;
  customerName?: string;
}

export interface Expense {
  id: string;
  timestamp: Date;
  description: string;
  amount: number;
  category: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { Product, CartItem, Category, Transaction, PaymentMethod, Expense } from './types';
import { INITIAL_PRODUCTS, TAX_RATE } from './constants';
import { POSView } from './components/POSView';
import { InventoryView } from './components/InventoryView';
import { HistoryView } from './components/HistoryView';
import { Receipt } from './components/Receipt';
import { AIAssistant } from './components/AIAssistant';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'pos' | 'inventory' | 'history'>('pos');
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);
  const [isAIOpen, setIsAIOpen] = useState(false);

  const barcodeInputRef = useRef<HTMLInputElement>(null);

  // Focus effect for the barcode input
  useEffect(() => {
    if (activeTab === 'pos' && !isReceiptOpen && !isAIOpen) {
      const timer = setTimeout(() => {
        barcodeInputRef.current?.focus();
      }, 100);
      return () => clearTimeout(timer);
    }
  }, [activeTab, isReceiptOpen, isAIOpen, cart]);

  const handleAddToCart = (product: Product) => {
    if (product.stock <= 0) return;
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) return prev;
        return prev.map(item => 
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const handleRemoveFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const handleUpdateQuantity = (productId: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === productId) {
        const newQty = item.quantity + delta;
        const prod = products.find(p => p.id === productId);
        if (prod && newQty > 0 && newQty <= prod.stock) {
          return { ...item, quantity: newQty };
        }
      }
      return item;
    }));
  };

  const handleCheckout = (paymentMethod: PaymentMethod, amountPaid: number, discount: number = 0, customerName: string = '') => {
    const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const tax = subtotal * TAX_RATE;
    const total = subtotal + tax - discount;
    const change = amountPaid - total;

    const newTransaction: Transaction = {
      id: `TRX-${Date.now()}`,
      timestamp: new Date(),
      items: [...cart],
      subtotal,
      tax,
      discount,
      total,
      paymentMethod,
      amountPaid,
      change,
      customerName
    };

    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(ci => ci.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    setTransactions(prev => [newTransaction, ...prev]);
    setLastTransaction(newTransaction);
    setCart([]);
    setIsReceiptOpen(true);
  };

  const handleAddExpense = (description: string, amount: number, category: string) => {
    const newExpense: Expense = {
      id: `EXP-${Date.now()}`,
      timestamp: new Date(),
      description,
      amount,
      category
    };
    setExpenses(prev => [newExpense, ...prev]);
