import React, { useState } from 'react';
import { Product, Category } from '../types';

interface InventoryViewProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  onAddExpense: (description: string, amount: number, category: string) => void;
}

export const InventoryView: React.FC<InventoryViewProps> = ({ products, setProducts, onAddExpense }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    barcode: '',
    category: Category.FOOD,
    price: 0,
    stock: 0
  });

  const handleSave = () => {
    if (!formData.name || !formData.barcode || !formData.price) return;
    if (editingId) {
      setProducts(prev => prev.map(p => p.id === editingId ? { ...p, ...formData } as Product : p));
      setEditingId(null);
    } else {
      const newProduct = { ...formData, id: Date.now().toString() } as Product;
      setProducts(prev => [...prev, newProduct]);
      // Log expense for initial stock if it's a new product
      if (formData.stock && formData.stock > 0) {
        onAddExpense(`Kulakan Awal: ${formData.name}`, (formData.price * 0.7) * (formData.stock || 0), 'Belanja Stok');
      }
      setIsAdding(false);
    }
    setFormData({ name: '', barcode: '', category: Category.FOOD, price: 0, stock: 0 });
  };

  const handleQuickRestock = (product: Product, amount: number) => {
    setProducts(prev => prev.map(p => p.id === product.id ? { ...p, stock: p.stock + amount } : p));
    // Assume buy price is 70% of sell price
    const totalCost = (product.price * 0.7) * amount;
    onAddExpense(`Restok: ${product.name} x${amount}`, totalCost, 'Belanja Stok');
  };

  return (
    <div className="h-full flex flex-col gap-6 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-black text-white tracking-tight">KONTROL INVENTARIS</h2>
          <p className="text-slate-500 text-sm">Kelola stok dan harga produk Anda</p>
        </div>
        <button 
          onClick={() => { setIsAdding(true); setEditingId(null); }}
          className="bg-indigo-600 hover:bg-indigo-500 text-white px-6 py-3 rounded-2xl font-black transition-all shadow-lg shadow-indigo-600/20 active:scale-95 flex items-center gap-2"
        >
          <span>➕</span> TAMBAH PRODUK
        </button>
      </div>

      <div className="flex-1 overflow-auto rounded-3xl border border-white/5 bg-slate-900/50 backdrop-blur-sm">
        <table className="w-full text-left">
          <thead className="bg-white/5 sticky top-0 border-b border-white/5 z-10">
            <tr>
              <th className="p-5 font-bold text-slate-400 uppercase text-[10px] tracking-widest">Produk</th>
              <th className="p-5 font-bold text-slate-400 uppercase text-[10px] tracking-widest">Kategori</th>
              <th className="p-5 font-bold text-slate-400 uppercase text-[10px] tracking-widest">Harga</th>
              <th className="p-5 font-bold text-slate-400 uppercase text-[10px] tracking-widest">Stok</th>
              <th className="p-5 font-bold text-slate-400 uppercase text-[10px] tracking-widest text-right">Aksi</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5">
            {products.map(product => (
              <tr key={product.id} className="hover:bg-white/5 transition-all group">
                <td className="p-5">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-slate-950 rounded-lg flex items-center justify-center border border-white/5 group-hover:border-indigo-500/30 transition-all text-xl">
                        {product.category === Category.FOOD ? '🍜' : 
                         product.category === Category.BEVERAGE ? '🥤' : 
                         product.category === Category.KITCHEN ? '🧂' : 
                         product.category === Category.SCHOOL ? '📓' : '🧼'}
                    </div>
                    <div>
                      <div className="font-bold text-slate-200">{product.name}</div>
                      <div className="text-[10px] font-mono text-slate-500">{product.barcode}</div>
                    </div>
                  </div>
                </td>
                <td className="p-5">
                  <span className="text-[10px] font-black uppercase tracking-widest px-2.5 py-1 bg-slate-800 text-slate-400 rounded-lg border border-white/5">
                    {product.category}
                  </span>
                </td>
                <td className="p-5">
                  <span className="font-bold text-indigo-400">Rp {product.price.toLocaleString()}</span>
                </td>
                <td className="p-5">
                   <div className="flex items-center gap-4">
                      <div className="flex items-center gap-2">
                        <div className={`w-2 h-2 rounded-full ${product.stock < 10 ? 'bg-rose-500 animate-ping' : 'bg-emerald-500'}`}></div>
                        <span className={`font-black ${product.stock < 10 ? 'text-rose-400' : 'text-slate-300'}`}>{product.stock}</span>
                      </div>
                      <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => handleQuickRestock(product, 10)} className="text-[10px] bg-indigo-500/20 text-indigo-400 px-2 py-1 rounded hover:bg-indigo-500/40 font-bold">+10</button>
                        <button onClick={() => handleQuickRestock(product, 50)} className="text-[10px] bg-indigo-500/20 text-indigo-400 px-2 py-1 rounded hover:bg-indigo-500/40 font-bold">+50</button>
                      </div>
                   </div>
                </td>
                <td className="p-5 text-right space-x-2 whitespace-nowrap">
                  <button onClick={() => { setFormData(product); setEditingId(product.id); setIsAdding(true); }} className="text-indigo-400 hover:text-indigo-300 font-bold text-xs transition-colors">EDIT</button>
                  <button onClick={() => setProducts(p => p.filter(x => x.id !== product.id))} className="text-slate-600 hover:text-rose-500 font-bold text-sm transition-colors">HAPUS</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-[130] p-4 backdrop-blur-md">
          <div className="bg-slate-900 border border-white/10 rounded-3xl shadow-2xl w-full max-w-md p-8 animate-in zoom-in duration-300 text-slate-200">
            <h3 className="text-2xl font-black mb-8 tracking-tight">{editingId ? 'UPDATE PRODUK' : 'PRODUK BARU'}</h3>
            <div className="space-y-5">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Nama Item</label>
                <input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-5 py-3 bg-slate-950 border border-white/5 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all"/>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Barcode</label>
                <input type="text" value={formData.barcode} onChange={e => setFormData({...formData, barcode: e.target.value})} className="w-full px-5 py-3 bg-slate-950 border border-white/5 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-mono"/>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Harga Jual (Rp)</label>
                  <input type="number" value={formData.price} onChange={e => setFormData({...formData, price: parseInt(e.target.value)})} className="w-full px-5 py-3 bg-slate-950 border border-white/5 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold"/>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Stok Awal</label>
                  <input type="number" value={formData.stock} onChange={e => setFormData({...formData, stock: parseInt(e.target.value)})} className="w-full px-5 py-3 bg-slate-950 border border-white/5 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold"/>
                </div>
              </div>
              {!editingId && (
                <div className="p-3 bg-amber-500/10 border border-amber-500/20 rounded-xl">
                  <p className="text-[10px] text-amber-500 font-bold uppercase leading-tight">Mencatat pengeluaran modal secara otomatis (Est. 70% harga jual per unit).</p>
                </div>
              )}
            </div>
            <div className="mt-10 flex gap-4">
              <button onClick={() => setIsAdding(false)} className="flex-1 py-4 bg-slate-800 hover:bg-slate-700 text-slate-400 font-black rounded-2xl transition-all">BATAL</button>
              <button onClick={handleSave} className="flex-1 py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-black rounded-2xl shadow-xl shadow-indigo-600/20 transition-all active:scale-95">SIMPAN</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Transaction, Expense } from '../types';

interface HistoryViewProps {
  transactions: Transaction[];
  expenses: Expense[];
}

export const HistoryView: React.FC<HistoryViewProps> = ({ transactions, expenses }) => {
  const [viewTab, setViewTab] = useState<'list' | 'analytics'>('analytics');

  const totalIncome = transactions.reduce((a, b) => a + b.total, 0);
  const totalExpense = expenses.reduce((a, b) => a + b.amount, 0);
  const netProfit = totalIncome - totalExpense;

  // Simple Analytics Logic for Chart (Last 7 Hours or Mock Data if empty)
  const incomePerHour = Array(12).fill(0);
  const expensePerHour = Array(12).fill(0);

  transactions.forEach(t => {
    const hour = t.timestamp.getHours() % 12;
    incomePerHour[hour] += t.total;
  });

  expenses.forEach(e => {
    const hour = e.timestamp.getHours() % 12;
    expensePerHour[hour] += e.amount;
  });

  const maxVal = Math.max(...incomePerHour, ...expensePerHour, 1);

  return (
    <div className="p-6 h-full flex flex-col space-y-6 overflow-hidden">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-black text-white tracking-tight">LAPORAN KEUANGAN</h2>
          <p className="text-slate-500 text-sm">Analisis Pemasukan & Pengeluaran Maziyyah Mart</p>
        </div>
        <div className="flex bg-slate-900 p-1 rounded-xl border border-white/5">
          <button 
            onClick={() => setViewTab('analytics')}
            className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${viewTab === 'analytics' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-500 hover:text-slate-300'}`}
          >
            📊 ANALITIK
          </button>
          <button 
            onClick={() => setViewTab('list')}
            className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${viewTab === 'list' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-500 hover:text-slate-300'}`}
          >
            📜 DAFTAR
          </button>
        </div>
      </div>

      {viewTab === 'analytics' ? (
        <div className="flex-1 overflow-y-auto space-y-6 pr-2">
          {/* Top Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="glass p-6 rounded-3xl border-l-4 border-l-emerald-500">
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Total Pemasukan</span>
              <div className="text-2xl font-black text-emerald-400 mt-1">Rp {totalIncome.toLocaleString()}</div>
              <div className="text-[10px] text-slate-400 mt-2 flex items-center gap-1">
                <span className="text-emerald-500">↑</span> Dari {transactions.length} Transaksi
              </div>
            </div>
            <div className="glass p-6 rounded-3xl border-l-4 border-l-rose-500">
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Total Pengeluaran</span>
              <div className="text-2xl font-black text-rose-400 mt-1">Rp {totalExpense.toLocaleString()}</div>
              <div className="text-[10px] text-slate-400 mt-2 flex items-center gap-1">
                <span className="text-rose-500">↓</span> Modal & Restok
              </div>
            </div>
            <div className={`glass p-6 rounded-3xl border-l-4 ${netProfit >= 0 ? 'border-l-indigo-500' : 'border-l-orange-500'}`}>
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Laba Bersih</span>
              <div className={`text-2xl font-black mt-1 ${netProfit >= 0 ? 'text-indigo-400' : 'text-orange-400'}`}>
                Rp {netProfit.toLocaleString()}
              </div>
              <div className="text-[10px] text-slate-400 mt-2">Saldo Real-time</div>
            </div>
          </div>

          {/* Chart Section */}
          <div className="glass rounded-3xl p-8 h-80 flex flex-col border border-white/5 relative overflow-hidden">
             <div className="flex justify-between items-center mb-10">
                <h3 className="font-black text-sm text-slate-400 uppercase tracking-widest">Visualisasi Arus Kas (Harian)</h3>
                <div className="flex gap-4">
                  <div className="flex items-center gap-2">
                    <div className="w-3 h-3 bg-indigo-500 rounded-sm"></div>
                    <span className="text-[10px] text-slate-500 font-bold uppercase">Pemasukan</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="w-3 h-3 bg-rose-500 rounded-sm"></div>
                    <span className="text-[10px] text-slate-500 font-bold uppercase">Pengeluaran</span>
                  </div>
                </div>
             </div>

             <div className="flex-1 flex items-end justify-between gap-3 px-2">
                {incomePerHour.map((inc, i) => {
                  const exp = expensePerHour[i];
                  const incHeight = (inc / maxVal) * 100;
                  const expHeight = (exp / maxVal) * 100;

                  return (
                    <div key={i} className="flex-1 flex flex-col items-center gap-1 group relative">
                       {/* Tooltip */}
                       <div className="absolute -top-12 bg-slate-900 border border-white/10 px-2 py-1 rounded text-[10px] opacity-0 group-hover:opacity-100 transition-opacity z-20 pointer-events-none whitespace-nowrap">
                          P: Rp {inc.toLocaleString()}<br/>
                          K: Rp {exp.toLocaleString()}
                       </div>

                       <div className="w-full flex items-end gap-1 h-40">
                          <div 
                            style={{ height: `${incHeight}%` }} 
                            className="flex-1 bg-indigo-600 rounded-t-md min-h-[4px] hover:bg-indigo-400 transition-all duration-500"
                          ></div>
                          <div 
                            style={{ height: `${expHeight}%` }} 
                            className="flex-1 bg-rose-600 rounded-t-md min-h-[4px] hover:bg-rose-400 transition-all duration-500"
                          ></div>
                       </div>
                       <span className="text-[8px] font-bold text-slate-600 mt-2">{i*2}:00</span>
                    </div>
                  )
                })}
             </div>
          </div>

          {/* Recent Expenses List */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pb-6">
            <div className="glass rounded-3xl overflow-hidden border border-white/5">
              <div className="p-4 bg-white/5 border-b border-white/5">
                <h4 className="text-[10px] font-black uppercase tracking-widest text-emerald-400">Pemasukan Terakhir</h4>
              </div>
              <div className="divide-y divide-white/5">
                {transactions.slice(0, 5).map(t => (
                  <div key={t.id} className="p-3 flex justify-between items-center hover:bg-white/5 transition-all">
                    <div>
                      <p className="text-xs font-bold text-slate-200 uppercase">{t.customerName || 'UMUM'}</p>
                      <p className="text-[9px] text-slate-500">{t.timestamp.toLocaleTimeString()}</p>
                    </div>
                    <span className="text-emerald-400 font-black text-sm">Rp {t.total.toLocaleString()}</span>
                  </div>
                ))}
                {transactions.length === 0 && <div className="p-6 text-center text-slate-600 text-xs">Belum ada pemasukan</div>}
              </div>
            </div>

            <div className="glass rounded-3xl overflow-hidden border border-white/5">
              <div className="p-4 bg-white/5 border-b border-white/5">
                <h4 className="text-[10px] font-black uppercase tracking-widest text-rose-400">Pengeluaran Terakhir</h4>
              </div>
              <div className="divide-y divide-white/5">
                {expenses.slice(0, 5).map(e => (
                  <div key={e.id} className="p-3 flex justify-between items-center hover:bg-white/5 transition-all">
                    <div>
                      <p className="text-xs font-bold text-slate-200 uppercase">{e.description}</p>
                      <p className="text-[9px] text-slate-500">{e.timestamp.toLocaleTimeString()}</p>
                    </div>
                    <span className="text-rose-400 font-black text-sm">Rp {e.amount.toLocaleString()}</span>
                  </div>
                ))}
                {expenses.length === 0 && <div className="p-6 text-center text-slate-600 text-xs">Belum ada pengeluaran</div>}
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="flex-1 overflow-auto rounded-3xl border border-white/5 bg-slate-900/50 backdrop-blur-sm">
          {transactions.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-slate-600 py-12">
              <span className="text-6xl mb-4">📄</span>
              <p className="text-lg">Belum ada transaksi hari ini</p>
            </div>
          ) : (
            <table className="w-full text-left">
              <thead className="bg-white/5 sticky top-0 border-b border-white/5 z-10">
                <tr>
                  <th className="p-4 font-bold text-slate-400 uppercase text-[10px] tracking-widest">Waktu</th>
                  <th className="p-4 font-bold text-slate-400 uppercase text-[10px] tracking-widest">Pembeli</th>
                  <th className="p-4 font-bold text-slate-400 uppercase text-[10px] tracking-widest">ID Transaksi</th>
                  <th className="p-4 font-bold text-slate-400 uppercase text-[10px] tracking-widest">Metode</th>
                  <th className="p-4 font-bold text-slate-400 uppercase text-[10px] tracking-widest">Total</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5 text-slate-300">
                {transactions.map(trx => (
                  <tr key={trx.id} className="hover:bg-white/5 transition-all group">
                    <td className="p-4">
                      <div className="text-slate-200 text-sm">{trx.timestamp.toLocaleDateString('id-ID')}</div>
                      <div className="text-slate-500 text-[10px]">{trx.timestamp.toLocaleTimeString('id-ID')}</div>
                    </td>
                    <td className="p-4">
                      <span className="text-slate-200 font-bold text-sm uppercase">{trx.customerName || 'Umum'}</span>
                    </td>
                    <td className="p-4">
                      <span className="font-mono text-xs text-slate-500">{trx.id}</span>
                    </td>
                    <td className="p-4">
                      <span className="bg-indigo-500/10 text-indigo-400 text-[10px] px-2 py-1 rounded-lg font-black uppercase tracking-widest border border-indigo-500/20">
                        {trx.paymentMethod}
                      </span>
                    </td>
                    <td className="p-4">
                      <span className="font-black text-slate-200">Rp {trx.total.toLocaleString()}</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Product, CartItem, Category, PaymentMethod } from '../types';
import { TAX_RATE } from '../constants';

interface POSViewProps {
  products: Product[];
  cart: CartItem[];
  onAddToCart: (product: Product) => void;
  onRemoveFromCart: (productId: string) => void;
  onUpdateQuantity: (productId: string, delta: number) => void;
  onCheckout: (paymentMethod: PaymentMethod, amountPaid: number, discount: number, customerName: string) => void;
  barcodeInputRef: React.RefObject<HTMLInputElement>;
}

export const POSView: React.FC<POSViewProps> = ({ 
  products, 
  cart, 
  onAddToCart, 
  onRemoveFromCart, 
  onUpdateQuantity, 
  onCheckout,
  barcodeInputRef
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [customerName, setCustomerName] = useState('');
  const [activeCategory, setActiveCategory] = useState<Category | 'All'>('All');
  const [paymentAmount, setPaymentAmount] = useState<string>('');
  const [discount, setDiscount] = useState<string>('0');
  const [selectedPayment, setSelectedPayment] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckoutModal, setShowCheckoutModal] = useState(false);

  // Focus search input when the internal checkout modal is closed
  useEffect(() => {
    if (!showCheckoutModal) {
      barcodeInputRef.current?.focus();
    }
  }, [showCheckoutModal]);

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  // Fitur Diskon Otomatis: 5% jika subtotal > 100.000
  const AUTO_DISCOUNT_THRESHOLD = 100000;
  const AUTO_DISCOUNT_RATE = 0.05;
  const autoDiscount = subtotal >= AUTO_DISCOUNT_THRESHOLD ? Math.floor(subtotal * AUTO_DISCOUNT_RATE) : 0;

  const tax = subtotal * TAX_RATE;
  const manualDiscount = parseFloat(discount) || 0;
  const totalCombinedDiscount = autoDiscount + manualDiscount;
  const total = subtotal + tax - totalCombinedDiscount;

  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.barcode.includes(searchTerm);
    const matchesCategory = activeCategory === 'All' || p.category === activeCategory;
    return matchesSearch && matchesCategory;
  });

  const lowStockCount = filteredProducts.filter(p => p.stock > 0 && p.stock < 10).length;

  const handleBarcodeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product = products.find(p => p.barcode === searchTerm);
    if (product) {
      onAddToCart(product);
      setSearchTerm('');
    }
  };

  const handleProcessPayment = () => {
    const paid = parseFloat(paymentAmount);
    if (paid < total) return;
    onCheckout(selectedPayment, paid, totalCombinedDiscount, customerName);
    setShowCheckoutModal(false);
    setPaymentAmount('');
    setCustomerName('');
    setDiscount('0');
