                )}
              </div>

              {selectedPayment === PaymentMethod.CASH && (
                <div className="space-y-3">
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-lg text-slate-500 font-bold">Rp</span>
                    <input 
                      autoFocus
                      type="number" 
                      value={paymentAmount} 
                      onChange={(e) => setPaymentAmount(e.target.value)}
                      className="w-full pl-12 pr-4 py-3 bg-slate-950 border border-white/5 rounded-xl text-2xl font-black outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-white"
                      placeholder="0"
                    />
                  </div>

                  {parseFloat(paymentAmount) >= total && (
                    <div className="p-3 bg-indigo-500/10 rounded-xl border border-indigo-500/20 flex justify-between items-center animate-in slide-in-from-bottom-1">
                      <span className="text-indigo-400 font-bold uppercase tracking-widest text-[10px]">Kembalian</span>
                      <span className="text-xl font-black text-indigo-400">Rp {(parseFloat(paymentAmount) - total).toLocaleString()}</span>
                    </div>
                  )}
                </div>
              )}
            </div>

            <div className="p-5 pt-0">
              <button 
                onClick={handleProcessPayment}
                className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white text-lg font-black rounded-xl shadow-lg shadow-indigo-600/30 transition-all active:scale-[0.98]"
              >
                KONFIRMASI LUNAS
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

