                        <span className="text-sm font-black w-4 text-center">{item.quantity}</span>
                        <button onClick={() => onUpdateQuantity(item.id, 1)} className="w-6 h-6 rounded-lg bg-slate-800 flex items-center justify-center text-xs hover:bg-indigo-600 transition-colors">+</button>
