import React, { useState, useEffect } from 'react';
import { Product, CartItem, Category, PaymentMethod } from '../types';
import { TAX_RATE } from '../constants';

interface POSViewProps {
  products: Product[];
  cart: CartItem[];
  onAddToCart: (product: Product) => void;
  onRemoveFromCart: (productId: string) => void;
  onUpdateQuantity: (productId: string, delta: number) => void;
  onCheckout: (paymentMethod: PaymentMethod, amountPaid: number, discount: number, customerName: string) => void;
  barcodeInputRef: React.RefObject<HTMLInputElement>;
}

export const POSView: React.FC<POSViewProps> = ({ 
  products, 
  cart, 
  onAddToCart, 
  onRemoveFromCart, 
  onUpdateQuantity, 
  onCheckout,
  barcodeInputRef
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [customerName, setCustomerName] = useState('');
  const [activeCategory, setActiveCategory] = useState<Category | 'All'>('All');
  const [paymentAmount, setPaymentAmount] = useState<string>('');
  const [discount, setDiscount] = useState<string>('0');
  const [selectedPayment, setSelectedPayment] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckoutModal, setShowCheckoutModal] = useState(false);

  useEffect(() => {
    if (!showCheckoutModal) {
      barcodeInputRef.current?.focus();
    }
  }, [showCheckoutModal]);

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const AUTO_DISCOUNT_THRESHOLD = 100000;
  const AUTO_DISCOUNT_RATE = 0.05;
  const autoDiscount = subtotal >= AUTO_DISCOUNT_THRESHOLD ? Math.floor(subtotal * AUTO_DISCOUNT_RATE) : 0;

  const tax = subtotal * TAX_RATE;
  const manualDiscount = parseFloat(discount) || 0;
  const totalCombinedDiscount = autoDiscount + manualDiscount;
  const total = subtotal + tax - totalCombinedDiscount;

  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.barcode.includes(searchTerm);
    const matchesCategory = activeCategory === 'All' || p.category === activeCategory;
    return matchesSearch && matchesCategory;
  });

  const handleBarcodeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product = products.find(p => p.barcode === searchTerm);
    if (product) {
      onAddToCart(product);
      setSearchTerm('');
    }
  };

  const handleProcessPayment = () => {
    const paid = (selectedPayment === PaymentMethod.CASH) ? parseFloat(paymentAmount) : total;
    if (isNaN(paid) || paid < total) return;
    onCheckout(selectedPayment, paid, totalCombinedDiscount, customerName);
    setShowCheckoutModal(false);
    setPaymentAmount('');
    setCustomerName('');
    setDiscount('0');
  };

  const getCategoryIcon = (cat: Category) => {
    switch(cat) {
      case Category.FOOD: return '🍜';
      case Category.BEVERAGE: return '🥤';
      case Category.KITCHEN: return '🧂';
      case Category.SCHOOL: return '📓';
      case Category.HOUSEHOLD: return '🧼';
      default: return '📦';
    }
  };

  const getStockStatus = (stock: number) => {
    if (stock <= 0) return { label: 'HABIS', color: 'bg-rose-500/20 text-rose-500 border-rose-500/30', bar: 'bg-rose-500' };
    if (stock < 10) return { label: 'KRITIS', color: 'bg-amber-500/20 text-amber-500 border-amber-500/30', bar: 'bg-amber-500' };
    return { label: 'TERSEDIA', color: 'bg-emerald-500/20 text-emerald-500 border-emerald-500/30', bar: 'bg-emerald-500' };
  };

  return (
    <div className="flex h-full gap-4 overflow-hidden">
      <div className="flex-1 flex flex-col gap-6 overflow-hidden">
        {/* Header Section: Search & Category Filter */}
        <div className="space-y-4">
          <div className="relative">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500">🔍</span>
            <form onSubmit={handleBarcodeSubmit}>
              <input 
                ref={barcodeInputRef}
                type="text" 
                placeholder="Scan barcode atau cari nama produk..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-12 pr-4 py-4 bg-slate-900/80 border border-white/5 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all text-slate-100 placeholder:text-slate-600 shadow-xl"
              />
            </form>
          </div>

          <div className="flex items-center gap-2 overflow-x-auto pb-2 no-scrollbar">
            <button 
              onClick={() => setActiveCategory('All')}
              className={`px-6 py-2.5 rounded-xl text-xs font-black tracking-widest uppercase transition-all whitespace-nowrap border ${activeCategory === 'All' ? 'bg-indigo-600 text-white border-indigo-400 shadow-lg shadow-indigo-600/30' : 'bg-slate-900 text-slate-500 border-white/5 hover:border-white/10'}`}
            >
              Semua Menu
            </button>
            {Object.values(Category).map(cat => (
              <button 
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-6 py-2.5 rounded-xl text-xs font-black tracking-widest uppercase transition-all whitespace-nowrap border flex items-center gap-2 ${activeCategory === cat ? 'bg-indigo-600 text-white border-indigo-400 shadow-lg shadow-indigo-600/30' : 'bg-slate-900 text-slate-500 border-white/5 hover:border-white/10'}`}
              >
                <span>{getCategoryIcon(cat)}</span>
                {cat}
              </button>
            ))}
          </div>
        </div>

        {/* Product Grid */}
        <div className="flex-1 overflow-y-auto grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4 pr-2 pb-6">
          {filteredProducts.map(product => {
            const status = getStockStatus(product.stock);
            const isOutOfStock = product.stock <= 0;

            return (
              <button 
                key={product.id}
                onClick={() => onAddToCart(product)}
                disabled={isOutOfStock}
                className={`group relative flex flex-col bg-slate-900/50 border rounded-3xl overflow-hidden transition-all text-left h-full hover:shadow-2xl hover:-translate-y-1 ${
                  isOutOfStock ? 'opacity-60 grayscale border-slate-800' : 'border-white/5 hover:border-indigo-500/50'
                }`}
              >
                <div className="relative aspect-square bg-slate-950 flex items-center justify-center overflow-hidden">
                  <div className="text-6xl group-hover:scale-125 transition-transform duration-500">
                    {getCategoryIcon(product.category)}
                  </div>
                  <div className={`absolute top-3 right-3 px-2 py-1 rounded-lg text-[9px] font-black border backdrop-blur-md ${status.color}`}>
                    {status.label}
                  </div>
                </div>

                <div className="p-4 flex-1 flex flex-col">
                  <div className="text-[10px] font-black text-indigo-400/70 uppercase tracking-widest mb-1">{product.category}</div>
                  <h3 className="font-bold text-slate-100 text-sm mb-1 line-clamp-2 leading-tight h-10">{product.name}</h3>
                  <p className="text-[10px] font-mono text-slate-600 mb-3">{product.barcode}</p>

                  <div className="mt-auto space-y-3">
                    <div className="flex justify-between items-end">
                      <div className="flex flex-col">
                        <span className="text-[10px] text-slate-500 font-bold uppercase">Harga</span>
                        <span className="text-lg font-black text-white tracking-tighter">Rp {product.price.toLocaleString()}</span>
                      </div>
                      <div className="text-right flex flex-col items-end">
                         <span className="text-[10px] text-slate-500 font-bold uppercase">Stok</span>
                         <span className={`text-xs font-black ${product.stock < 10 ? 'text-amber-500' : 'text-slate-400'}`}>{product.stock} Unit</span>
                      </div>
                    </div>
                    <div className="w-full h-1 bg-slate-800 rounded-full overflow-hidden">
                       <div 
                         className={`h-full ${status.bar} transition-all duration-500`} 
                         style={{ width: `${Math.min((product.stock / 50) * 100, 100)}%` }}
                       ></div>
                    </div>
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* Cart Panel */}
      <div className="w-96 glass rounded-3xl flex flex-col overflow-hidden border border-white/5 shadow-2xl">
        <div className="p-6 border-b border-white/5 bg-slate-900/30">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-black text-xl tracking-tight text-white uppercase">KERANJANG</h2>
            <div className="bg-indigo-600 text-white text-[10px] font-black px-3 py-1 rounded-lg shadow-lg shadow-indigo-600/20">{cart.length} ITEM</div>
          </div>
          <div className="relative">
            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 text-sm">👤</span>
            <input 
              type="text" 
              placeholder="Input nama pelanggan..." 
              value={customerName}
              onChange={(e) => setCustomerName(e.target.value)}
              className="w-full pl-10 pr-3 py-2.5 bg-slate-950/50 border border-white/10 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all text-slate-200 placeholder:text-slate-700 font-medium"
            />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-700 opacity-40">
              <div className="text-6xl mb-4">🛒</div>
              <p className="font-black text-sm uppercase tracking-widest">Belum ada barang</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex gap-4 p-3 rounded-2xl bg-white/5 border border-white/5 group hover:bg-white/10 transition-all items-center">
                <div className="w-12 h-12 bg-slate-950 rounded-xl flex items-center justify-center text-xl shrink-0">
                  {getCategoryIcon(item.category)}
                </div>
                <div className="flex-1 min-w-0">
                  <h4 className="font-bold text-sm text-slate-100 truncate">{item.name}</h4>
                  <div className="flex justify-between items-center mt-1">
                    <span className="text-xs text-indigo-400 font-black">Rp {item.price.toLocaleString()}</span>
                    <div className="flex items-center gap-2">
                        <button onClick={() => onUpdateQuantity(item.id, -1)} className="w-7 h-7 rounded-lg bg-slate-800 text-slate-300 flex items-center justify-center hover:bg-rose-600 hover:text-white transition-all font-black">-</button>
                        <span className="text-sm font-black w-6 text-center text-white">{item.quantity}</span>
                        <button onClick={() => onUpdateQuantity(item.id, 1)} className="w-7 h-7 rounded-lg bg-slate-800 text-slate-300 flex items-center justify-center hover:bg-indigo-600 hover:text-white transition-all font-black">+</button>
