import React, { useState, useEffect, useRef } from 'react';
import { Product, CartItem, Category, Transaction, PaymentMethod, Expense } from './types';
import { INITIAL_PRODUCTS, TAX_RATE } from './constants';
import { POSView } from './components/POSView';
import { InventoryView } from './components/InventoryView';
import { HistoryView } from './components/HistoryView';
import { Receipt } from './components/Receipt';
import { AIAssistant } from './components/AIAssistant';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'pos' | 'inventory' | 'history'>('pos');
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);
  const [isAIOpen, setIsAIOpen] = useState(false);

  const barcodeInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (activeTab === 'pos' && !isReceiptOpen && !isAIOpen) {
      const timer = setTimeout(() => {
        barcodeInputRef.current?.focus();
      }, 100);
      return () => clearTimeout(timer);
    }
  }, [activeTab, isReceiptOpen, isAIOpen, cart]);

  const handleAddToCart = (product: Product) => {
    if (product.stock <= 0) return;
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) return prev;
        return prev.map(item => 
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const handleRemoveFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const handleUpdateQuantity = (productId: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === productId) {
        const newQty = item.quantity + delta;
        const prod = products.find(p => p.id === productId);
        if (prod && newQty > 0 && newQty <= prod.stock) {
          return { ...item, quantity: newQty };
        }
      }
      return item;
    }));
  };

  const handleCheckout = (paymentMethod: PaymentMethod, amountPaid: number, discount: number = 0, customerName: string = '') => {
    const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const tax = subtotal * TAX_RATE;
    const total = subtotal + tax - discount;
    const change = amountPaid - total;

    const newTransaction: Transaction = {
      id: `TRX-${Date.now()}`,
      timestamp: new Date(),
      items: [...cart],
      subtotal,
      tax,
      discount,
      total,
      paymentMethod,
      amountPaid,
      change,
      customerName
    };

    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(ci => ci.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    setTransactions(prev => [newTransaction, ...prev]);
    setLastTransaction(newTransaction);
    setCart([]);
    setIsReceiptOpen(true);
  };

  const handleAddExpense = (description: string, amount: number, category: string) => {
    const newExpense: Expense = {
      id: `EXP-${Date.now()}`,
      timestamp: new Date(),
      description,
      amount,
      category
    };
    setExpenses(prev => [newExpense, ...prev]);
  };

  return (
    <div className="flex h-screen overflow-hidden bg-slate-50 text-slate-800">
      {/* Sidebar */}
      <aside className="w-20 md:w-64 bg-white border-r border-slate-200 flex flex-col no-print z-20 shadow-sm">
        <div className="p-6 flex items-center space-x-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <span className="text-xl">🏪</span>
          </div>
          <div className="font-bold text-xl hidden md:block text-slate-900">
            Maziyyah<span className="text-indigo-600">Mart</span> <span className="text-[10px] bg-indigo-100 px-1.5 py-0.5 rounded text-indigo-600 font-black">PRO</span>
          </div>
        </div>

        <nav className="flex-1 mt-6 px-3 space-y-2">
          {[
            { id: 'pos', icon: '🛒', label: 'Penjualan' },
            { id: 'inventory', icon: '📦', label: 'Inventaris' },
            { id: 'history', icon: '📊', label: 'Laporan' },
          ].map((tab) => (
            <button 
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`w-full p-3 rounded-xl flex items-center space-x-4 transition-all ${activeTab === tab.id ? 'bg-indigo-50 text-indigo-600 border border-indigo-100 shadow-sm' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <span className="text-xl">{tab.icon}</span>
              <span className="hidden md:block font-bold">{tab.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-4 no-print">
          <button 
            onClick={() => setIsAIOpen(true)}
            className="w-full bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 p-3 rounded-xl flex items-center justify-center space-x-2 shadow-lg shadow-indigo-200 transition-all active:scale-95 text-white"
          >
            <span className="text-xl animate-pulse">✨</span>
            <span className="hidden md:block font-bold">Tanya AI</span>
          </button>
        </div>

        <div className="p-6 border-t border-slate-100">
           <div className="hidden md:flex items-center space-x-3">
              <div className="w-8 h-8 rounded-full bg-indigo-100 border border-indigo-200 flex items-center justify-center text-xs font-bold text-indigo-600">S</div>
              <div className="text-xs">
                <p className="font-bold text-slate-900">Sukron</p>
                <p className="text-slate-500">Admin Mart</p>
              </div>
           </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden relative no-print">
        <header className="h-16 border-b border-slate-200 flex items-center justify-between px-8 bg-white/80 backdrop-blur-md">
          <div className="flex items-center space-x-4">
            <h1 className="text-sm font-black uppercase tracking-[0.2em] text-slate-400">{activeTab}</h1>
            <div className="h-4 w-[1px] bg-slate-200"></div>
            <div className="text-xs text-slate-500 font-bold uppercase tracking-wider">Terminal #001</div>
          </div>
          <div className="flex items-center space-x-6">
            <div className="flex flex-col items-end">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Omset Hari ini</span>
                <span className="text-sm font-black text-slate-900">Rp {transactions.reduce((a,b) => a + b.total, 0).toLocaleString()}</span>
            </div>
            <div className="w-10 h-10 rounded-full bg-slate-100 border border-slate-200 flex items-center justify-center text-lg">👨‍💼</div>
          </div>
        </header>

        <div className="flex-1 overflow-auto bg-slate-50 p-6">
          {activeTab === 'pos' && (
            <POSView 
              products={products}
              cart={cart}
              onAddToCart={handleAddToCart}
              onRemoveFromCart={handleRemoveFromCart}
              onUpdateQuantity={handleUpdateQuantity}
              onCheckout={handleCheckout}
              barcodeInputRef={barcodeInputRef}
            />
          )}
          {activeTab === 'inventory' && (
            <InventoryView 
              products={products} 
              setProducts={setProducts} 
              onAddExpense={handleAddExpense}
            />
          )}
          {activeTab === 'history' && (
            <HistoryView 
              transactions={transactions} 
              expenses={expenses}
            />
          )}
        </div>
      </main>

      {/* AI Assistant Side Panel */}
      {isAIOpen && (
        <div className="no-print">
          <AIAssistant 
            onClose={() => setIsAIOpen(false)} 
            products={products} 
            transactions={transactions}
          />
        </div>
      )}

      {/* Receipt Modal Overlay */}
      {isReceiptOpen && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/40 flex items-center justify-center z-[100] p-4 backdrop-blur-sm no-print">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden flex flex-col max-h-[90vh] scale-in border border-white">
            <div className="flex-1 overflow-auto p-6 bg-white">
              <Receipt transaction={lastTransaction} />
            </div>
            <div className="p-5 bg-slate-50 border-t border-slate-100 flex space-x-3">
              <button onClick={() => window.print()} className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white font-black py-3 rounded-2xl transition shadow-lg shadow-indigo-200">Cetak Struk</button>
              <button onClick={() => setIsReceiptOpen(false)} className="flex-1 bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 font-black py-3 rounded-2xl transition shadow-sm">Selesai</button>
            </div>
          </div>
        </div>
      )}

      {/* Hidden container for actual printing */}
      {isReceiptOpen && lastTransaction && (
        <div className="print-only">
          <Receipt transaction={lastTransaction} />
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, Category, PaymentMethod } from '../types';
import { TAX_RATE } from '../constants';

interface POSViewProps {
  products: Product[];
  cart: CartItem[];
  onAddToCart: (product: Product) => void;
  onRemoveFromCart: (productId: string) => void;
  onUpdateQuantity: (productId: string, delta: number) => void;
  onCheckout: (paymentMethod: PaymentMethod, amountPaid: number, discount: number, customerName: string) => void;
  barcodeInputRef: React.RefObject<HTMLInputElement>;
}

export const POSView: React.FC<POSViewProps> = ({ 
  products, 
  cart, 
  onAddToCart, 
  onRemoveFromCart, 
  onUpdateQuantity, 
  onCheckout,
  barcodeInputRef
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [customerName, setCustomerName] = useState('');
  const [activeCategory, setActiveCategory] = useState<Category | 'All'>('All');
  const [paymentAmount, setPaymentAmount] = useState<string>('');
  const [discount, setDiscount] = useState<string>('0');
  const [selectedPayment, setSelectedPayment] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckoutModal, setShowCheckoutModal] = useState(false);

  useEffect(() => {
    if (!showCheckoutModal) {
      barcodeInputRef.current?.focus();
    }
  }, [showCheckoutModal]);

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const AUTO_DISCOUNT_THRESHOLD = 100000;
  const AUTO_DISCOUNT_RATE = 0.05;
  const autoDiscount = subtotal >= AUTO_DISCOUNT_THRESHOLD ? Math.floor(subtotal * AUTO_DISCOUNT_RATE) : 0;

  const tax = subtotal * TAX_RATE;
  const manualDiscount = parseFloat(discount) || 0;
  const totalCombinedDiscount = autoDiscount + manualDiscount;
  const total = subtotal + tax - totalCombinedDiscount;

  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.barcode.includes(searchTerm);
    const matchesCategory = activeCategory === 'All' || p.category === activeCategory;
    return matchesSearch && matchesCategory;
  });

  const handleBarcodeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product = products.find(p => p.barcode === searchTerm);
    if (product) {
      onAddToCart(product);
      setSearchTerm('');
    }
  };

  const handleProcessPayment = () => {
    const paid = (selectedPayment === PaymentMethod.CASH) ? parseFloat(paymentAmount) : total;
    if (isNaN(paid) || paid < total) return;
    onCheckout(selectedPayment, paid, totalCombinedDiscount, customerName);
    setShowCheckoutModal(false);
    setPaymentAmount('');
    setCustomerName('');
    setDiscount('0');
  };

  const getCategoryIcon = (cat: Category) => {
    switch(cat) {
      case Category.FOOD: return '🍜';
      case Category.BEVERAGE: return '🥤';
      case Category.KITCHEN: return '🧂';
      case Category.SCHOOL: return '📓';
      case Category.HOUSEHOLD: return '🧼';
      default: return '📦';
    }
  };

  const getStockStatus = (stock: number) => {
    if (stock <= 0) return { label: 'HABIS', color: 'bg-rose-100 text-rose-600 border-rose-200', bar: 'bg-rose-500' };
    if (stock < 10) return { label: 'KRITIS', color: 'bg-amber-100 text-amber-600 border-amber-200', bar: 'bg-amber-500' };
    return { label: 'TERSEDIA', color: 'bg-emerald-100 text-emerald-600 border-emerald-200', bar: 'bg-emerald-500' };
  };

  return (
    <div className="flex h-full gap-6 overflow-hidden">
      <div className="flex-1 flex flex-col gap-6 overflow-hidden">
        {/* Header Section */}
        <div className="space-y-5">
          <div className="relative">
            <span className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400">🔍</span>
            <form onSubmit={handleBarcodeSubmit}>
              <input 
                ref={barcodeInputRef}
                type="text" 
                placeholder="Scan barcode atau cari nama produk..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-14 pr-6 py-4 bg-white border border-slate-200 rounded-2xl outline-none focus:ring-4 focus:ring-indigo-50 transition-all text-slate-900 placeholder:text-slate-400 shadow-sm font-medium"
              />
            </form>
          </div>

          <div className="flex items-center gap-3 overflow-x-auto pb-2 no-scrollbar">
            <button 
              onClick={() => setActiveCategory('All')}
              className={`px-6 py-3 rounded-2xl text-[10px] font-black tracking-widest uppercase transition-all whitespace-nowrap border ${activeCategory === 'All' ? 'bg-indigo-600 text-white border-indigo-500 shadow-md shadow-indigo-100' : 'bg-white text-slate-500 border-slate-200 hover:border-indigo-200'}`}
            >
              Semua Menu
            </button>
            {Object.values(Category).map(cat => (
              <button 
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-6 py-3 rounded-2xl text-[10px] font-black tracking-widest uppercase transition-all whitespace-nowrap border flex items-center gap-2 ${activeCategory === cat ? 'bg-indigo-600 text-white border-indigo-500 shadow-md shadow-indigo-100' : 'bg-white text-slate-500 border-slate-200 hover:border-indigo-200'}`}
              >
                <span>{getCategoryIcon(cat)}</span>
                {cat}
              </button>
            ))}
          </div>
        </div>

        {/* Product Grid */}
        <div className="flex-1 overflow-y-auto grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5 pr-2 pb-6">
          {filteredProducts.map(product => {
            const status = getStockStatus(product.stock);
            const isOutOfStock = product.stock <= 0;

            return (
              <button 
                key={product.id}
                onClick={() => onAddToCart(product)}
                disabled={isOutOfStock}
                className={`group relative flex flex-col bg-white border rounded-[2rem] overflow-hidden transition-all text-left h-full hover:shadow-xl hover:shadow-indigo-900/5 hover:-translate-y-1 ${
                  isOutOfStock ? 'opacity-60 grayscale border-slate-100' : 'border-slate-100 hover:border-indigo-100'
                }`}
              >
                <div className="relative aspect-square bg-slate-50 flex items-center justify-center overflow-hidden">
                  <div className="text-6xl group-hover:scale-110 transition-transform duration-500 drop-shadow-sm">
                    {getCategoryIcon(product.category)}
                  </div>
                  <div className={`absolute top-4 right-4 px-2.5 py-1.5 rounded-xl text-[8px] font-black border backdrop-blur-md ${status.color}`}>
                    {status.label}
                  </div>
                </div>

                <div className="p-5 flex-1 flex flex-col">
                  <div className="text-[9px] font-black text-indigo-500/70 uppercase tracking-[0.2em] mb-2">{product.category}</div>
                  <h3 className="font-bold text-slate-900 text-sm mb-1 line-clamp-2 leading-tight h-10">{product.name}</h3>
                  <p className="text-[10px] font-mono text-slate-400 mb-4">{product.barcode}</p>

                  <div className="mt-auto space-y-4">
                    <div className="flex justify-between items-end">
                      <div className="flex flex-col">
                        <span className="text-[9px] text-slate-400 font-black uppercase tracking-widest">Harga</span>
                        <span className="text-lg font-black text-slate-900 tracking-tight">Rp {product.price.toLocaleString()}</span>
                      </div>
                      <div className="text-right flex flex-col items-end">
                         <span className="text-[9px] text-slate-400 font-black uppercase tracking-widest">Stok</span>
                         <span className={`text-xs font-black ${product.stock < 10 ? 'text-amber-500' : 'text-slate-500'}`}>{product.stock} Pcs</span>
                      </div>
                    </div>
                    <div className="w-full h-1.5 bg-slate-100 rounded-full overflow-hidden">
                       <div 
                         className={`h-full ${status.bar} transition-all duration-700 ease-out`} 
                         style={{ width: `${Math.min((product.stock / 50) * 100, 100)}%` }}
                       ></div>
                    </div>
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* Cart Panel */}
      <div className="w-[26rem] bg-white rounded-[2.5rem] flex flex-col overflow-hidden border border-slate-200 shadow-xl shadow-slate-200/50">
        <div className="p-8 border-b border-slate-100 bg-slate-50/50">
          <div className="flex items-center justify-between mb-6">
            <h2 className="font-black text-xl tracking-tight text-slate-900 uppercase">KERANJANG</h2>
            <div className="bg-indigo-600 text-white text-[10px] font-black px-3 py-1.5 rounded-xl shadow-lg shadow-indigo-200">{cart.length} ITEM</div>
          </div>
          <div className="relative">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 text-sm">👤</span>
            <input 
              type="text" 
              placeholder="Nama Pelanggan..." 
              value={customerName}
              onChange={(e) => setCustomerName(e.target.value)}
              className="w-full pl-11 pr-4 py-3 bg-white border border-slate-200 rounded-2xl text-sm outline-none focus:ring-4 focus:ring-indigo-50 transition-all text-slate-700 placeholder:text-slate-400 font-bold"
            />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-300">
              <div className="text-7xl mb-4 opacity-30">🛒</div>
              <p className="font-black text-xs uppercase tracking-widest text-slate-400">Keranjang masih kosong</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex gap-4 p-4 rounded-3xl bg-slate-50 border border-slate-100 group hover:bg-white hover:border-indigo-100 hover:shadow-md transition-all items-center">
                <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center text-2xl shrink-0 shadow-sm border border-slate-100">
                  {getCategoryIcon(item.category)}
                </div>
                <div className="flex-1 min-w-0">
                  <h4 className="font-black text-xs text-slate-800 truncate uppercase">{item.name}</h4>
                  <div className="flex justify-between items-center mt-2">
                    <span className="text-sm text-indigo-600 font-black">Rp {item.price.toLocaleString()}</span>
                    <div className="flex items-center gap-2">
                        <button onClick={() => onUpdateQuantity(item.id, -1)} className="w-8 h-8 rounded-xl bg-white border border-slate-200 text-slate-500 flex items-center justify-center hover:bg-rose-50 hover:text-rose-600 hover:border-rose-100 transition-all font-black shadow-sm">-</button>
                        <span className="text-xs font-black w-6 text-center text-slate-900">{item.quantity}</span>
                        <button onClick={() => onUpdateQuantity(item.id, 1)} className="w-8 h-8 rounded-xl bg-white border border-slate-200 text-slate-500 flex items-center justify-center hover:bg-indigo-50 hover:text-indigo-600 hover:border-indigo-100 transition-all font-black shadow-sm">+</button>
                    </div>
                  </div>
                </div>
                <button onClick={() => onRemoveFromCart(item.id)} className="p-2 text-slate-300 hover:text-rose-500 transition-colors">✕</button>
              </div>
            ))
          )}
        </div>

        <div className="p-8 bg-slate-50 border-t border-slate-200 space-y-5">
          <div className="space-y-3">
            <div className="flex justify-between text-slate-400 text-[10px] font-black uppercase tracking-widest">
              <span>Subtotal</span>
              <span className="text-slate-700 font-mono">Rp {subtotal.toLocaleString()}</span>
            </div>
            {autoDiscount > 0 && (
              <div className="flex justify-between text-emerald-600 text-[10px] font-black uppercase tracking-widest">
                <span className="flex items-center gap-2">
                  <span className="bg-emerald-100 px-1.5 py-0.5 rounded text-[8px] border border-emerald-200">LOYALTY 5%</span>
                </span>
                <span className="font-mono">- Rp {autoDiscount.toLocaleString()}</span>
              </div>
            )}
            <div className="flex justify-between text-slate-400 text-[10px] font-black uppercase tracking-widest">
              <span>Pajak (PPN 11%)</span>
              <span className="text-slate-700 font-mono">Rp {tax.toLocaleString()}</span>
            </div>
            <div className="flex justify-between items-center text-slate-400 text-[10px] font-black uppercase tracking-widest pt-1">
              <span>Potongan Manual</span>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[10px] text-slate-400 font-mono">Rp</span>
                <input 
                  type="number" 
                  value={discount} 
                  onChange={(e) => setDiscount(e.target.value)}
                  className="w-32 text-right pl-8 pr-3 py-2 bg-white border border-slate-200 rounded-xl text-xs outline-none focus:ring-4 focus:ring-indigo-50 text-slate-900 font-mono font-bold"
                />
              </div>
            </div>
          </div>
          <div className="pt-6 border-t border-slate-200 flex justify-between items-center">
            <div className="flex flex-col">
               <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] leading-none mb-2">Total Tagihan</span>
               <span className="text-4xl font-black text-slate-950 tracking-tighter">Rp {total.toLocaleString()}</span>
            </div>
          </div>
          <button 
            disabled={cart.length === 0}
            onClick={() => {
              setPaymentAmount(total.toString());
              setShowCheckoutModal(true);
            }}
            className="w-full py-5 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-200 disabled:text-slate-400 text-white rounded-[1.5rem] font-black text-lg transition-all shadow-xl shadow-indigo-100 active:scale-[0.98] flex items-center justify-center gap-3"
          >
            <span>💳</span> BAYAR SEKARANG
          </button>
        </div>
      </div>

      {/* Checkout Modal */}
      {showCheckoutModal && (
        <div className="fixed inset-0 bg-slate-900/60 flex items-center justify-center z-[110] p-4 backdrop-blur-md">
          <div className="bg-white border border-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden flex flex-col animate-in fade-in zoom-in duration-200">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <div className="flex items-center gap-3">
                <span className="text-2xl">💳</span>
                <h2 className="text-xl font-black tracking-tight text-slate-900 uppercase">PROSES PEMBAYARAN</h2>
              </div>
              <button onClick={() => setShowCheckoutModal(false)} className="w-8 h-8 flex items-center justify-center rounded-full bg-slate-100 text-slate-400 hover:text-slate-600 transition-colors">✕</button>
            </div>

            <div className="p-8 space-y-8 overflow-y-auto max-h-[80vh]">
              <div className="flex items-center justify-between p-4 bg-indigo-50 rounded-2xl border border-indigo-100 text-xs">
                <span className="text-indigo-400 font-black uppercase tracking-widest">Pelanggan:</span>
                <span className="text-indigo-600 font-black uppercase">{customerName || 'UMUM'}</span>
              </div>

              <div className="grid grid-cols-2 gap-4">
                {Object.values(PaymentMethod).map(method => (
                  <button 
                    key={method}
                    onClick={() => setSelectedPayment(method)}
                    className={`p-4 border-2 rounded-2xl flex flex-col items-center gap-2 transition-all ${selectedPayment === method ? 'border-indigo-600 bg-indigo-50 text-indigo-600 shadow-sm shadow-indigo-100' : 'border-slate-100 bg-slate-50 hover:bg-white hover:border-slate-200 text-slate-400'}`}
                  >
                    <span className="text-3xl">
                      {method === PaymentMethod.CASH ? '💵' : method === PaymentMethod.QRIS ? '📱' : method === PaymentMethod.DEBIT ? '💳' : '👛'}
                    </span>
                    <span className="font-black text-[10px] uppercase tracking-widest">{method}</span>
                  </button>
                ))}
              </div>

              <div className="text-center py-4 bg-slate-50 rounded-[2rem] border border-slate-100">
                <span className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">Total Tagihan</span>
                <div className="text-4xl font-black text-slate-900 mt-1 tracking-tighter">Rp {total.toLocaleString()}</div>
                {totalCombinedDiscount > 0 && (
                  <div className="text-[10px] text-emerald-600 font-black mt-2 tracking-widest uppercase">(HEMAT RP {totalCombinedDiscount.toLocaleString()})</div>
                )}
              </div>

              {selectedPayment === PaymentMethod.QRIS && (
                <div className="flex flex-col items-center gap-5 py-6 bg-white rounded-3xl shadow-xl border border-slate-100 animate-in zoom-in">
                  <div className="text-slate-900 font-black text-[10px] tracking-widest uppercase">SCAN QRIS PEMBAYARAN</div>
                  <div className="w-44 h-44 bg-slate-50 p-3 rounded-2xl border border-slate-100 relative group overflow-hidden">
                    <div className="w-full h-full grid grid-cols-10 grid-rows-10 opacity-80">
                      {Array.from({length: 100}).map((_, i) => (
                        <div key={i} className={`w-full h-full ${Math.random() > 0.5 ? 'bg-slate-900' : 'bg-transparent'}`}></div>
                      ))}
                    </div>
                    <div className="absolute inset-0 bg-indigo-600/5 group-hover:opacity-0 transition-opacity"></div>
                  </div>
                  <div className="text-indigo-600 font-black text-sm tracking-tight uppercase">Nominal: Rp {total.toLocaleString()}</div>
                </div>
              )}

              {selectedPayment === PaymentMethod.CASH && (
                <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Uang Tunai Diterima</label>
                    <div className="relative">
                      <span className="absolute left-4 top-1/2 -translate-y-1/2 text-xl text-slate-400 font-black">Rp</span>
                      <input 
                        autoFocus
                        type="number" 
                        value={paymentAmount} 
                        onChange={(e) => setPaymentAmount(e.target.value)}
                        className="w-full pl-16 pr-6 py-5 bg-slate-50 border border-slate-200 rounded-2xl text-3xl font-black outline-none focus:ring-4 focus:ring-indigo-50 text-slate-900"
                        placeholder="0"
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-3 gap-3">
                    {[50000, 100000, 200000].map(val => (
                      <button key={val} onClick={() => setPaymentAmount(val.toString())} className="py-3 bg-white border border-slate-200 hover:border-indigo-600 hover:text-indigo-600 text-slate-500 text-[10px] font-black rounded-xl transition-all shadow-sm">Rp {val.toLocaleString()}</button>
                    ))}
                  </div>
                  {parseFloat(paymentAmount) >= total && (
                    <div className="p-5 bg-emerald-50 rounded-[1.5rem] border border-emerald-100 flex justify-between items-center animate-in slide-in-from-top">
                      <span className="text-emerald-600 font-black text-[10px] uppercase tracking-widest">Uang Kembalian</span>
                      <span className="text-2xl font-black text-emerald-600">Rp {(parseFloat(paymentAmount) - total).toLocaleString()}</span>
                    </div>
                  )}
                </div>
              )}
            </div>

            <div className="p-8 pt-0">
              <button 
                onClick={handleProcessPayment}
                disabled={selectedPayment === PaymentMethod.CASH && (parseFloat(paymentAmount) < total || !paymentAmount)}
                className="w-full py-5 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-200 disabled:text-slate-400 text-white text-xl font-black rounded-2xl shadow-xl shadow-indigo-100 transition-all active:scale-[0.98]"
              >
                KONFIRMASI LUNAS
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Product, Category } from '../types';

interface InventoryViewProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  onAddExpense: (description: string, amount: number, category: string) => void;
}

export const InventoryView: React.FC<InventoryViewProps> = ({ products, setProducts, onAddExpense }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    barcode: '',
    category: Category.FOOD,
    price: 0,
    stock: 0
  });

  const handleSave = () => {
    if (!formData.name || !formData.barcode || !formData.price) return;
    if (editingId) {
      setProducts(prev => prev.map(p => p.id === editingId ? { ...p, ...formData } as Product : p));
      setEditingId(null);
    } else {
      const newProduct = { ...formData, id: Date.now().toString() } as Product;
      setProducts(prev => [...prev, newProduct]);
      if (formData.stock && formData.stock > 0) {
        onAddExpense(`Kulakan Awal: ${formData.name}`, (formData.price * 0.7) * (formData.stock || 0), 'Belanja Stok');
      }
      setIsAdding(false);
    }
    setFormData({ name: '', barcode: '', category: Category.FOOD, price: 0, stock: 0 });
  };

  const handleQuickRestock = (product: Product, amount: number) => {
    setProducts(prev => prev.map(p => p.id === product.id ? { ...p, stock: p.stock + amount } : p));
    const totalCost = (product.price * 0.7) * amount;
    onAddExpense(`Restok: ${product.name} x${amount}`, totalCost, 'Belanja Stok');
  };

  return (
    <div className="h-full flex flex-col gap-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">KONTROL INVENTARIS</h2>
          <p className="text-slate-500 text-sm mt-1">Kelola stok barang dan pengaturan harga minimarket</p>
        </div>
        <button 
          onClick={() => { setIsAdding(true); setEditingId(null); }}
          className="bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-4 rounded-[1.5rem] font-black transition-all shadow-xl shadow-indigo-100 active:scale-95 flex items-center gap-3"
        >
          <span>➕</span> TAMBAH PRODUK BARU
        </button>
      </div>

      <div className="flex-1 overflow-auto rounded-[2rem] border border-slate-200 bg-white shadow-xl shadow-slate-200/50">
        <table className="w-full text-left">
          <thead className="bg-slate-50/50 sticky top-0 border-b border-slate-100 z-10 backdrop-blur-md">
            <tr>
              <th className="p-6 font-black text-slate-400 uppercase text-[10px] tracking-[0.2em]">Data Produk</th>
              <th className="p-6 font-black text-slate-400 uppercase text-[10px] tracking-[0.2em]">Kategori</th>
              <th className="p-6 font-black text-slate-400 uppercase text-[10px] tracking-[0.2em]">Harga Jual</th>
              <th className="p-6 font-black text-slate-400 uppercase text-[10px] tracking-[0.2em]">Stok</th>
              <th className="p-6 font-black text-slate-400 uppercase text-[10px] tracking-[0.2em] text-right">Manajemen</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {products.map(product => (
              <tr key={product.id} className="hover:bg-slate-50 transition-all group">
                <td className="p-6">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center border border-slate-100 group-hover:border-indigo-100 group-hover:bg-white transition-all text-2xl shadow-sm">
                        {product.category === Category.FOOD ? '🍜' : 
                         product.category === Category.BEVERAGE ? '🥤' : 
                         product.category === Category.KITCHEN ? '🧂' : 
                         product.category === Category.SCHOOL ? '📓' : '🧼'}
                    </div>
                    <div>
                      <div className="font-black text-slate-900 text-sm uppercase">{product.name}</div>
                      <div className="text-[10px] font-mono text-slate-400 tracking-wider">{product.barcode}</div>
                    </div>
                  </div>
                </td>
                <td className="p-6">
                  <span className="text-[9px] font-black uppercase tracking-widest px-3 py-1.5 bg-indigo-50 text-indigo-600 rounded-xl border border-indigo-100">
                    {product.category}
                  </span>
                </td>
                <td className="p-6">
                  <span className="font-black text-slate-900">Rp {product.price.toLocaleString()}</span>
                </td>
                <td className="p-6">
                   <div className="flex items-center gap-5">
                      <div className="flex items-center gap-2">
                        <div className={`w-2 h-2 rounded-full ${product.stock < 10 ? 'bg-rose-500 animate-pulse' : 'bg-emerald-500'}`}></div>
                        <span className={`font-black text-sm ${product.stock < 10 ? 'text-rose-600' : 'text-slate-700'}`}>{product.stock}</span>
                      </div>
                      <div className="flex gap-1.5 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => handleQuickRestock(product, 10)} className="text-[9px] bg-white border border-slate-200 text-slate-500 px-2.5 py-1.5 rounded-lg hover:border-indigo-600 hover:text-indigo-600 font-black shadow-sm">+10</button>
                        <button onClick={() => handleQuickRestock(product, 50)} className="text-[9px] bg-white border border-slate-200 text-slate-500 px-2.5 py-1.5 rounded-lg hover:border-indigo-600 hover:text-indigo-600 font-black shadow-sm">+50</button>
                      </div>
                   </div>
