                <td className="p-6 text-right space-x-3 whitespace-nowrap">
                  <button onClick={() => { setFormData(product); setEditingId(product.id); setIsAdding(true); }} className="text-indigo-600 hover:text-indigo-800 font-black text-xs uppercase tracking-widest transition-colors">Edit</button>
                  <button onClick={() => setProducts(p => p.filter(x => x.id !== product.id))} className="text-slate-300 hover:text-rose-500 font-black text-xs uppercase tracking-widest transition-colors">Hapus</button>
                </td>
              </tr>
            ))}
