import React, { useState } from 'react';
import { Transaction, Expense, PaymentMethod } from '../types';

interface HistoryViewProps {
  transactions: Transaction[];
  expenses: Expense[];
}

export const HistoryView: React.FC<HistoryViewProps> = ({ transactions, expenses }) => {
  const [viewTab, setViewTab] = useState<'list' | 'analytics'>('analytics');
  const [methodFilter, setMethodFilter] = useState<PaymentMethod | 'All'>('All');

  const filteredTransactions = transactions.filter(t => 
    methodFilter === 'All' ? true : t.paymentMethod === methodFilter
  );

  const totalIncome = filteredTransactions.reduce((a, b) => a + b.total, 0);
  const totalExpense = expenses.reduce((a, b) => a + b.amount, 0);
  const netProfit = totalIncome - totalExpense;

  const incomePerHour = Array(12).fill(0);
  const expensePerHour = Array(12).fill(0);

  filteredTransactions.forEach(t => {
    const hour = t.timestamp.getHours() % 12;
    incomePerHour[hour] += t.total;
  });

  expenses.forEach(e => {
    const hour = e.timestamp.getHours() % 12;
    expensePerHour[hour] += e.amount;
  });

  const maxVal = Math.max(...incomePerHour, ...expensePerHour, 1);

  return (
    <div className="h-full flex flex-col space-y-8 overflow-hidden animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-5">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">LAPORAN KEUANGAN</h2>
          <p className="text-slate-500 text-sm mt-1">Ringkasan performa penjualan Maziyyah Mart</p>
        </div>

        <div className="flex flex-wrap gap-3 items-center">
          <div className="flex bg-white p-1.5 rounded-[1.25rem] border border-slate-200 shadow-sm">
            <select 
              value={methodFilter}
              onChange={(e) => setMethodFilter(e.target.value as any)}
              className="bg-transparent text-xs font-black text-slate-600 px-4 py-2 outline-none cursor-pointer uppercase tracking-widest"
            >
              <option value="All">Semua Metode</option>
              {Object.values(PaymentMethod).map(method => (
                <option key={method} value={method}>{method}</option>
              ))}
            </select>
          </div>

          <div className="flex bg-white p-1.5 rounded-[1.25rem] border border-slate-200 shadow-sm">
            <button 
              onClick={() => setViewTab('analytics')}
              className={`px-5 py-2.5 rounded-xl text-[10px] font-black tracking-widest transition-all ${viewTab === 'analytics' ? 'bg-indigo-600 text-white shadow-md shadow-indigo-100' : 'text-slate-400 hover:text-slate-600'}`}
            >
              📊 ANALITIK
            </button>
            <button 
              onClick={() => setViewTab('list')}
              className={`px-5 py-2.5 rounded-xl text-[10px] font-black tracking-widest transition-all ${viewTab === 'list' ? 'bg-indigo-600 text-white shadow-md shadow-indigo-100' : 'text-slate-400 hover:text-slate-600'}`}
            >
              📜 DAFTAR
            </button>
          </div>
        </div>
      </div>

      {viewTab === 'analytics' ? (
        <div className="flex-1 overflow-y-auto space-y-8 pr-2 custom-scrollbar pb-10">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div className="bg-white p-8 rounded-[2.5rem] border-l-8 border-l-emerald-500 shadow-xl shadow-slate-200/50">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Total Pemasukan</span>
              <div className="text-3xl font-black text-emerald-600 mt-2 tracking-tighter">Rp {totalIncome.toLocaleString()}</div>
              <div className="text-[10px] text-slate-500 mt-4 flex items-center gap-2 font-bold uppercase tracking-widest">
                <span className="bg-emerald-100 text-emerald-600 px-1.5 py-0.5 rounded-lg border border-emerald-200">↑</span> {filteredTransactions.length} Transaksi Selesai
              </div>
            </div>
            <div className="bg-white p-8 rounded-[2.5rem] border-l-8 border-l-rose-500 shadow-xl shadow-slate-200/50">
