                <span className="bg-rose-100 text-rose-600 px-1.5 py-0.5 rounded-lg border border-rose-200">↓</span> Belanja Stok & Operasional
              </div>
            </div>
            <div className={`bg-white p-8 rounded-[2.5rem] border-l-8 shadow-xl shadow-slate-200/50 ${netProfit >= 0 ? 'border-l-indigo-500' : 'border-l-orange-500'}`}>
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Laba Bersih</span>
              <div className={`text-3xl font-black mt-2 tracking-tighter ${netProfit >= 0 ? 'text-indigo-600' : 'text-orange-600'}`}>
                Rp {netProfit.toLocaleString()}
