                  const incHeight = (inc / maxVal) * 100;
                  const expHeight = (exp / maxVal) * 100;

                  return (
                    <div key={i} className="flex-1 flex flex-col items-center gap-2 group relative">
                       <div className="absolute -top-16 bg-slate-900 text-white px-3 py-2 rounded-xl text-[10px] font-bold opacity-0 group-hover:opacity-100 transition-all duration-300 z-20 pointer-events-none whitespace-nowrap shadow-xl">
                          P: Rp {inc.toLocaleString()}<br/>
                          K: Rp {exp.toLocaleString()}
                       </div>

                       <div className="w-full flex items-end gap-1.5 h-48">
                          <div 
                            style={{ height: `${incHeight}%` }} 
                            className="flex-1 bg-indigo-600 rounded-t-xl min-h-[4px] hover:bg-indigo-400 transition-all duration-500 shadow-sm"
