        content: 'Halo! Saya asisten pintar SmartPOS. Anda bisa bertanya tentang ketersediaan stok, ringkasan penjualan, atau rekomendasi strategi toko hari ini.'
      }]);
    }
  }, []);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMessage }]);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const productContext = products.map(p => `- ${p.name} (Barcode: ${p.barcode}, Stok: ${p.stock}, Harga: Rp ${p.price})`).join('\n');
      const salesContext = `Total transaksi hari ini: ${transactions.length}. Total pendapatan: Rp ${transactions.reduce((a,b) => a + b.total, 0).toLocaleString()}`;

      const systemPrompt = `Anda adalah asisten cerdas untuk sistem POS minimarket Maziyyah Mart. 
      Latar belakang Anda: Profesional, efisien, dan membantu kasir/admin.

      DATA PRODUK TERKINI:
      ${productContext}

      PENJUALAN HARI INI:
      ${salesContext}

      TUGAS:
      1. Jawab pertanyaan terkait data di atas.
      2. Berikan saran jika stok barang di bawah 10 unit.
      3. Gunakan Bahasa Indonesia yang ramah namun profesional.
      4. Jawaban harus singkat dan padat (langsung ke intinya).`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMessage,
        config: {
          systemInstruction: systemPrompt,
          temperature: 0.7,
        }
      });

      setMessages(prev => [...prev, { role: 'ai', content: response.text || 'Maaf, sistem tidak memberikan respon.' }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', content: 'Terjadi gangguan koneksi ke server AI.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed right-0 top-0 bottom-0 w-[24rem] bg-white border-l border-slate-200 z-[120] flex flex-col shadow-2xl animate-in slide-in-from-right duration-300">
      <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-gradient-to-r from-indigo-50 to-white">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 rounded-[1rem] bg-indigo-600 flex items-center justify-center shadow-lg shadow-indigo-200 text-xl">✨</div>
          <div>
            <h2 className="font-black text-slate-900 tracking-tight uppercase text-sm">Smart AI Assistant</h2>
            <p className="text-[10px] text-indigo-500 font-black uppercase tracking-widest">Online & Ready</p>
          </div>
        </div>
        <button onClick={onClose} className="w-8 h-8 flex items-center justify-center rounded-full bg-slate-100 text-slate-400 hover:text-slate-600 transition-colors">✕</button>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-6 bg-slate-50/30">
        {messages.map((msg, i) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[90%] p-4 rounded-[1.5rem] text-sm font-medium leading-relaxed shadow-sm ${
              msg.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-tr-none' 
                : 'bg-white border border-slate-100 text-slate-700 rounded-tl-none'
            }`}>
              {msg.content}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white border border-slate-100 p-5 rounded-[1.5rem] rounded-tl-none flex gap-1.5 shadow-sm">
              <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce"></div>
              <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce delay-100"></div>
              <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce delay-200"></div>
            </div>
          </div>
        )}
      </div>

      <div className="p-6 border-t border-slate-100 bg-white">
        <div className="flex gap-3">
          <input 
            type="text" 
            placeholder="Ketik pertanyaan Anda..." 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            className="flex-1 bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm outline-none focus:ring-4 focus:ring-indigo-50 transition-all font-bold text-slate-800 placeholder:text-slate-400"
          />
          <button 
            onClick={handleSend}
            disabled={isLoading}
            className="bg-indigo-600 hover:bg-indigo-700 w-14 rounded-2xl transition-all disabled:opacity-50 flex items-center justify-center text-white shadow-lg shadow-indigo-100"
          >
            🚀
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Product, CartItem, Category, Transaction, PaymentMethod, Expense } from './types';
import { INITIAL_PRODUCTS, TAX_RATE } from './constants';
import { POSView } from './components/POSView';
import { InventoryView } from './components/InventoryView';
import { HistoryView } from './components/HistoryView';
import { Receipt } from './components/Receipt';
import { AIAssistant } from './components/AIAssistant';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'pos' | 'inventory' | 'history'>('pos');
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);
  const [isAIOpen, setIsAIOpen] = useState(false);

  const barcodeInputRef = useRef<HTMLInputElement>(null);

  const handleAddToCart = (product: Product) => {
    if (product.stock <= 0) return;
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) return prev;
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const handleCheckout = (paymentMethod: PaymentMethod, amountPaid: number, discount: number = 0, customerName: string = '') => {
    const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const tax = subtotal * TAX_RATE;
    const total = subtotal + tax - discount;
    const change = amountPaid - total;

    const newTransaction: Transaction = {
      id: `TRX-${Date.now()}`,
      timestamp: new Date(),
      items: [...cart],
      subtotal,
      tax,
      discount,
      total,
      paymentMethod,
      amountPaid,
      change,
      customerName
    };

    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(ci => ci.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    setTransactions(prev => [newTransaction, ...prev]);
    setLastTransaction(newTransaction);
    setCart([]);
    setIsReceiptOpen(true);
  };

  return (
    <div className="flex h-screen overflow-hidden bg-[#fafafa]">
      {/* Sidebar - Ultra Clean */}
      <aside className="w-24 md:w-64 bg-white border-r border-slate-100 flex flex-col z-30 no-print">
        <div className="h-24 flex items-center px-8">
          <div className="w-10 h-10 bg-indigo-600 rounded-2xl flex items-center justify-center shadow-2xl shadow-indigo-200">
            <span className="text-white font-black text-xl">M</span>
          </div>
          <div className="ml-4 hidden md:block">
            <h1 className="font-extrabold text-slate-900 tracking-tight text-lg leading-none">Maziyyah</h1>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Retail System</p>
          </div>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-8">
          {[
            { id: 'pos', icon: '🛒', label: 'Kasir' },
            { id: 'inventory', icon: '📦', label: 'Stok' },
            { id: 'history', icon: '📈', label: 'Laporan' },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full group flex items-center p-4 rounded-2xl transition-all duration-300 ${activeTab === item.id ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-50'}`}
            >
              <span className={`text-xl transition-transform duration-300 group-hover:scale-110 ${activeTab === item.id ? 'opacity-100' : 'opacity-40'}`}>{item.icon}</span>
              <span className="ml-4 hidden md:block font-bold text-sm tracking-tight">{item.label}</span>
              {activeTab === item.id && <div className="ml-auto w-1.5 h-1.5 rounded-full bg-indigo-600 shadow-glow"></div>}
            </button>
          ))}
        </nav>

        <div className="p-6">
          <button 
            onClick={() => setIsAIOpen(true)}
            className="w-full bg-slate-900 text-white p-4 rounded-2xl flex items-center justify-center gap-3 hover:bg-slate-800 transition-all shadow-xl shadow-slate-200"
          >
            <span className="text-lg">✨</span>
            <span className="hidden md:block font-bold text-xs uppercase tracking-widest">Asisten AI</span>
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col overflow-hidden relative">
        {/* Elegant Header */}
        <header className="h-24 bg-white/70 backdrop-blur-xl border-b border-slate-50 flex items-center justify-between px-10 no-print">
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em]">Halaman Utama</span>
            <h2 className="text-2xl font-black text-slate-900 capitalize tracking-tight">{activeTab}</h2>
          </div>

          <div className="flex items-center gap-8">
            <div className="text-right">
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Sesi Hari Ini</p>
              <p className="font-black text-slate-900 text-lg tracking-tight">Rp {transactions.reduce((a, b) => a + b.total, 0).toLocaleString()}</p>
            </div>
            <div className="h-10 w-[1px] bg-slate-100"></div>
            <div className="flex items-center gap-3 bg-slate-50 p-2 rounded-2xl border border-slate-100">
               <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center text-lg">👨‍💼</div>
               <div className="pr-2 hidden lg:block">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Admin</p>
                  <p className="text-xs font-bold text-slate-800">Sukron Mazid</p>
               </div>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-auto p-10">
          {activeTab === 'pos' && (
            <POSView 
              products={products}
              cart={cart}
              onAddToCart={handleAddToCart}
              onRemoveFromCart={(id) => setCart(prev => prev.filter(i => i.id !== id))}
              onUpdateQuantity={(id, d) => setCart(prev => prev.map(i => i.id === id ? {...i, quantity: Math.max(1, i.quantity + d)} : i))}
              onCheckout={handleCheckout}
              barcodeInputRef={barcodeInputRef}
            />
          )}
          {activeTab === 'inventory' && <InventoryView products={products} setProducts={setProducts} onAddExpense={() => {}} />}
          {activeTab === 'history' && <HistoryView transactions={transactions} expenses={expenses} />}
        </main>
      </div>

      {isAIOpen && <AIAssistant onClose={() => setIsAIOpen(false)} products={products} transactions={transactions} />}

      {isReceiptOpen && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/10 backdrop-blur-md flex items-center justify-center z-[100] p-4 no-print animate-in fade-in duration-500">
           <div className="bg-white rounded-[3rem] shadow-2xl p-8 max-w-sm w-full border border-slate-100">
              <Receipt transaction={lastTransaction} />
              <div className="mt-8 flex gap-3">
                 <button onClick={() => window.print()} className="flex-1 bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-indigo-200 hover:bg-indigo-700 transition-all">Cetak</button>
                 <button onClick={() => setIsReceiptOpen(false)} className="flex-1 bg-slate-50 text-slate-400 font-bold py-4 rounded-2xl hover:bg-slate-100 transition-all">Tutup</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

