  const [cart, setCart] = useState<CartItem[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);
  const [isAIOpen, setIsAIOpen] = useState(false);

  const barcodeInputRef = useRef<HTMLInputElement>(null);

  const handleAddToCart = (product: Product) => {
    if (product.stock <= 0) return;
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) return prev;
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const handleCheckout = (paymentMethod: PaymentMethod, amountPaid: number, discount: number = 0, customerName: string = '') => {
    const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const tax = subtotal * TAX_RATE;
    const total = subtotal + tax - discount;
    const change = amountPaid - total;

    const newTransaction: Transaction = {
      id: `TRX-${Date.now()}`,
      timestamp: new Date(),
      items: [...cart],
      subtotal,
      tax,
      discount,
      total,
      paymentMethod,
      amountPaid,
      change,
      customerName
    };

    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(ci => ci.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    setTransactions(prev => [newTransaction, ...prev]);
    setLastTransaction(newTransaction);
    setCart([]);
    setIsReceiptOpen(true);
  };

  return (
    <div className="flex h-screen overflow-hidden bg-[#fafbfc]">
      {/* Sidebar - Modern Fresh */}
      <aside className="w-24 md:w-64 glass-sidebar border-r border-slate-100 flex flex-col z-30 no-print">
        <div className="h-28 flex items-center px-10">
          <div className="w-12 h-12 gradient-orange rounded-2xl flex items-center justify-center shadow-lg shadow-orange-200 rotate-3">
            <span className="text-white font-black text-2xl -rotate-3">M</span>
          </div>
          <div className="ml-5 hidden md:block">
            <h1 className="font-extrabold text-slate-900 tracking-tight text-xl leading-none">Maziyyah</h1>
            <p className="text-[10px] text-emerald-500 font-black uppercase tracking-[0.2em] mt-1.5">Fresh Mart</p>
          </div>
        </div>

        <nav className="flex-1 px-6 space-y-3 mt-10">
          {[
            { id: 'pos', icon: '🛒', label: 'Kasir Utama', color: 'text-orange-500', bg: 'bg-orange-50' },
            { id: 'inventory', icon: '📦', label: 'Stok Barang', color: 'text-emerald-500', bg: 'bg-emerald-50' },
            { id: 'history', icon: '📊', label: 'Laporan', color: 'text-slate-500', bg: 'bg-slate-50' },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full group flex items-center p-4 rounded-3xl transition-all duration-500 ${activeTab === item.id ? `${item.bg} ${item.color} shadow-sm border border-black/5` : 'text-slate-400 hover:bg-slate-50'}`}
            >
              <span className={`text-xl transition-all duration-500 group-hover:scale-125 ${activeTab === item.id ? 'opacity-100' : 'opacity-40 grayscale'}`}>{item.icon}</span>
              <span className="ml-4 hidden md:block font-bold text-xs uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-8">
          <button 
            onClick={() => setIsAIOpen(true)}
            className="w-full gradient-green text-white p-4 rounded-3xl flex items-center justify-center gap-3 hover:opacity-90 transition-all shadow-xl shadow-emerald-100"
          >
            <span className="text-lg">✨</span>
            <span className="hidden md:block font-extrabold text-[10px] uppercase tracking-[0.2em]">Tanya AI</span>
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col overflow-hidden">
        {/* Elegant Minimal Header */}
        <header className="h-28 flex items-center justify-between px-12 no-print bg-white/40 backdrop-blur-md">
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-slate-300 uppercase tracking-[0.4em]"> Maziyyah System v2 </span>
            <h2 className="text-3xl font-black text-slate-900 capitalize tracking-tighter mt-1">{activeTab}</h2>
          </div>

          <div className="flex items-center gap-10">
            <div className="text-right">
              <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest">Penjualan Hari Ini</p>
              <p className="font-black text-slate-900 text-2xl tracking-tighter">Rp {transactions.reduce((a, b) => a + b.total, 0).toLocaleString()}</p>
            </div>
            <div className="flex items-center gap-4 bg-white px-5 py-3 rounded-3xl shadow-premium border border-slate-50">
               <div className="w-10 h-10 rounded-2xl gradient-orange flex items-center justify-center text-white font-bold">SM</div>
               <div className="hidden lg:block">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none">Kasir Aktif</p>
                  <p className="text-xs font-bold text-slate-800 mt-1">Sukron Mazid</p>
               </div>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-auto p-12">
          {activeTab === 'pos' && (
            <POSView 
              products={products}
              cart={cart}
              onAddToCart={handleAddToCart}
              onRemoveFromCart={(id) => setCart(prev => prev.filter(i => i.id !== id))}
              onUpdateQuantity={(id, d) => setCart(prev => prev.map(i => i.id === id ? {...i, quantity: Math.max(1, i.quantity + d)} : i))}
              onCheckout={handleCheckout}
              barcodeInputRef={barcodeInputRef}
            />
          )}
          {activeTab === 'inventory' && <InventoryView products={products} setProducts={setProducts} onAddExpense={() => {}} />}
          {activeTab === 'history' && <HistoryView transactions={transactions} expenses={expenses} />}
        </main>
      </div>

      {isAIOpen && <AIAssistant onClose={() => setIsAIOpen(false)} products={products} transactions={transactions} />}

      {isReceiptOpen && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/10 backdrop-blur-lg flex items-center justify-center z-[100] p-4 no-print animate-in fade-in zoom-in duration-500">
           <div className="bg-white rounded-[4rem] shadow-2xl p-10 max-w-sm w-full border border-white">
              <Receipt transaction={lastTransaction} />
              <div className="mt-10 flex gap-4">
                 <button onClick={() => window.print()} className="flex-1 gradient-orange text-white font-black py-5 rounded-[2rem] shadow-xl shadow-orange-100 hover:opacity-90 transition-all">Cetak Struk</button>
                 <button onClick={() => setIsReceiptOpen(false)} className="flex-1 bg-slate-100 text-slate-400 font-bold py-5 rounded-[2rem] hover:bg-slate-200 transition-all">Selesai</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

