import React, { useState, useEffect, useRef } from 'react';
import { Product, CartItem, Category, Transaction, PaymentMethod, Expense } from './types';
import { INITIAL_PRODUCTS, TAX_RATE } from './constants';
import { POSView } from './components/POSView';
import { InventoryView } from './components/InventoryView';
import { HistoryView } from './components/HistoryView';
import { Receipt } from './components/Receipt';
import { AIAssistant } from './components/AIAssistant';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'pos' | 'inventory' | 'history'>('pos');
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);
  const [isAIOpen, setIsAIOpen] = useState(false);

  const barcodeInputRef = useRef<HTMLInputElement>(null);

  const handleAddToCart = (product: Product) => {
    if (product.stock <= 0) return;
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) return prev;
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const handleCheckout = (paymentMethod: PaymentMethod, amountPaid: number, discount: number = 0, customerName: string = '') => {
    const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const tax = subtotal * TAX_RATE;
    const total = subtotal + tax - discount;
    const change = amountPaid - total;

    const newTransaction: Transaction = {
      id: `TRX-${Date.now()}`,
      timestamp: new Date(),
      items: [...cart],
      subtotal,
      tax,
      discount,
      total,
      paymentMethod,
      amountPaid,
      change,
      customerName
    };

    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(ci => ci.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    setTransactions(prev => [newTransaction, ...prev]);
    setLastTransaction(newTransaction);
    setCart([]);
    setIsReceiptOpen(true);
  };

  return (
    <div className="flex h-screen overflow-hidden bg-[#020617] text-slate-200">
      {/* Sidebar - Luxury Glass */}
      <aside className="w-24 md:w-64 glass-dark flex flex-col z-30 no-print">
        <div className="h-28 flex items-center px-8">
          <div className="w-12 h-12 gradient-dark-orange rounded-2xl flex items-center justify-center shadow-lg shadow-orange-900/40">
            <span className="text-white font-black text-2xl">M</span>
          </div>
          <div className="ml-4 hidden md:block">
            <h1 className="font-extrabold text-white tracking-tight text-xl leading-none">Maziyyah</h1>
            <p className="text-[10px] text-emerald-500 font-black uppercase tracking-[0.2em] mt-1">Obsidian POS</p>
          </div>
        </div>

        <nav className="flex-1 px-4 space-y-3 mt-10">
          {[
            { id: 'pos', icon: '🛒', label: 'Kasir', color: 'text-orange-500', bg: 'bg-orange-500/10' },
            { id: 'inventory', icon: '📦', label: 'Stok', color: 'text-emerald-500', bg: 'bg-emerald-500/10' },
            { id: 'history', icon: '📊', label: 'Laporan', color: 'text-slate-400', bg: 'bg-slate-800' },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full group flex items-center p-4 rounded-2xl transition-all duration-500 ${activeTab === item.id ? `${item.bg} ${item.color} border border-white/5` : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}
            >
              <span className={`text-xl transition-all duration-300 ${activeTab === item.id ? 'opacity-100 scale-110' : 'opacity-40'}`}>{item.icon}</span>
              <span className="ml-4 hidden md:block font-bold text-xs uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-6">
          <button 
            onClick={() => setIsAIOpen(true)}
            className="w-full bg-slate-800 border border-white/5 text-white p-4 rounded-2xl flex items-center justify-center gap-3 hover:bg-slate-700 transition-all"
          >
            <span className="text-lg">✨</span>
            <span className="hidden md:block font-extrabold text-[10px] uppercase tracking-widest">Asisten AI</span>
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col overflow-hidden relative">
        {/* Obsidian Header */}
        <header className="h-28 flex items-center justify-between px-10 no-print border-b border-white/5">
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.4em]">Maziyyah Terminal v2.5</span>
            <h2 className="text-3xl font-black text-white capitalize tracking-tighter mt-1">{activeTab}</h2>
          </div>

          <div className="flex items-center gap-10">
            <div className="text-right">
              <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest">Revenue Hari Ini</p>
              <p className="font-black text-white text-2xl tracking-tighter">Rp {transactions.reduce((a, b) => a + b.total, 0).toLocaleString()}</p>
            </div>
            <div className="h-10 w-[1px] bg-white/5"></div>
            <div className="flex items-center gap-3 bg-slate-900 px-4 py-2 rounded-2xl border border-white/5">
               <div className="w-8 h-8 rounded-lg gradient-dark-orange flex items-center justify-center text-white text-xs font-bold shadow-glow">SM</div>
               <div className="hidden lg:block">
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest leading-none">Kasir</p>
                  <p className="text-xs font-bold text-slate-300 mt-1">Sukron Mazid</p>
               </div>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-auto p-10 bg-[#020617]">
          {activeTab === 'pos' && (
            <POSView 
              products={products}
              cart={cart}
              onAddToCart={handleAddToCart}
              onRemoveFromCart={(id) => setCart(prev => prev.filter(i => i.id !== id))}
              onUpdateQuantity={(id, d) => setCart(prev => prev.map(i => i.id === id ? {...i, quantity: Math.max(1, i.quantity + d)} : i))}
              onCheckout={handleCheckout}
              barcodeInputRef={barcodeInputRef}
            />
          )}
          {activeTab === 'inventory' && <InventoryView products={products} setProducts={setProducts} onAddExpense={() => {}} />}
          {activeTab === 'history' && <HistoryView transactions={transactions} expenses={expenses} />}
        </main>
      </div>

      {isAIOpen && <AIAssistant onClose={() => setIsAIOpen(false)} products={products} transactions={transactions} />}

      {isReceiptOpen && lastTransaction && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex items-center justify-center z-[100] p-4 no-print animate-in fade-in duration-500">
           <div className="bg-white rounded-[2rem] p-8 max-w-sm w-full shadow-2xl">
              <Receipt transaction={lastTransaction} />
              <div className="mt-8 flex gap-3">
                 <button onClick={() => window.print()} className="flex-1 bg-orange-600 text-white font-black py-4 rounded-xl shadow-lg shadow-orange-900/20 hover:bg-orange-700 transition-all">Cetak</button>
                 <button onClick={() => setIsReceiptOpen(false)} className="flex-1 bg-slate-100 text-slate-400 font-bold py-4 rounded-xl hover:bg-slate-200 transition-all">Selesai</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

