  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);
  const [isAIOpen, setIsAIOpen] = useState(false);

  const barcodeInputRef = useRef<HTMLInputElement>(null);

  const handleAddToCart = (product: Product) => {
    if (product.stock <= 0) return;
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) return prev;
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const handleCheckout = (paymentMethod: PaymentMethod, amountPaid: number, discount: number = 0, customerName: string = '') => {
    const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const tax = subtotal * TAX_RATE;
    const total = subtotal + tax - discount;
    const change = amountPaid - total;

    const newTransaction: Transaction = {
      id: `TRX-${Date.now()}`,
      timestamp: new Date(),
      items: [...cart],
      subtotal,
      tax,
      discount,
      total,
      paymentMethod,
      amountPaid,
      change,
      customerName
    };

    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(ci => ci.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    setTransactions(prev => [newTransaction, ...prev]);
    setLastTransaction(newTransaction);
    setCart([]);
    setIsReceiptOpen(true);
  };

  return (
    <div className="flex h-screen overflow-hidden bg-[#020617] text-slate-200">
      {/* Sidebar - Compact Luxury */}
      <aside className="w-20 md:w-56 glass-dark flex flex-col z-30 no-print">
        <div className="h-20 flex items-center px-6">
          <div className="w-10 h-10 gradient-dark-orange rounded-xl flex items-center justify-center shadow-glow-orange">
            <span className="text-white font-black text-xl">M</span>
          </div>
          <div className="ml-3 hidden md:block">
            <h1 className="font-extrabold text-white text-sm leading-none">Maziyyah</h1>
            <p className="text-[8px] text-emerald-500 font-black uppercase tracking-widest mt-1">Terminal</p>
          </div>
        </div>

        <nav className="flex-1 px-3 space-y-2 mt-8">
          {[
            { id: 'pos', icon: '🛒', label: 'Kasir', color: 'text-orange-500', bg: 'bg-orange-500/10' },
            { id: 'inventory', icon: '📦', label: 'Stok', color: 'text-emerald-500', bg: 'bg-emerald-500/10' },
            { id: 'history', icon: '📊', label: 'Laporan', color: 'text-slate-400', bg: 'bg-slate-800/40' },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full group flex items-center p-3.5 rounded-xl transition-all ${activeTab === item.id ? `${item.bg} ${item.color} border border-white/5` : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}
            >
              <span className="text-lg">{item.icon}</span>
              <span className="ml-3 hidden md:block font-bold text-[10px] uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-4">
          <button 
            onClick={() => setIsAIOpen(true)}
            className="w-full bg-slate-800/50 border border-white/5 text-white p-3 rounded-xl flex items-center justify-center gap-2 hover:bg-slate-700 transition-all"
          >
            <span className="text-base">✨</span>
            <span className="hidden md:block font-extrabold text-[9px] uppercase tracking-widest">AI</span>
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col overflow-hidden relative">
        {/* Header - Compact */}
        <header className="h-20 flex items-center justify-between px-8 no-print border-b border-white/5">
          <div className="flex items-center gap-4">
            <h2 className="text-xl font-black text-white capitalize tracking-tight">{activeTab}</h2>
            <div className="h-4 w-[1px] bg-white/10"></div>
            <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">v2.5 Terminal</span>
          </div>

          <div className="flex items-center gap-8">
            <div className="text-right hidden sm:block">
              <p className="text-[8px] font-black text-emerald-500 uppercase tracking-widest">Daily Revenue</p>
              <p className="font-black text-white text-lg leading-tight">Rp {transactions.reduce((a, b) => a + b.total, 0).toLocaleString()}</p>
            </div>
            <div className="flex items-center gap-2.5 bg-slate-900/50 px-3 py-1.5 rounded-xl border border-white/5">
               <div className="w-7 h-7 rounded-lg gradient-dark-orange flex items-center justify-center text-white text-[10px] font-bold">SM</div>
               <div className="hidden lg:block text-left">
                  <p className="text-[8px] font-black text-slate-500 uppercase leading-none">Kasir</p>
                  <p className="text-[10px] font-bold text-slate-300 mt-0.5">Sukron</p>
               </div>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-auto p-6 bg-[#020617]">
          {activeTab === 'pos' && (
            <POSView 
              products={products}
              cart={cart}
              onAddToCart={handleAddToCart}
              onRemoveFromCart={(id) => setCart(prev => prev.filter(i => i.id !== id))}
              onUpdateQuantity={(id, d) => setCart(prev => prev.map(i => i.id === id ? {...i, quantity: Math.max(1, i.quantity + d)} : i))}
              onCheckout={handleCheckout}
              barcodeInputRef={barcodeInputRef}
            />
          )}
          {activeTab === 'inventory' && <InventoryView products={products} setProducts={setProducts} onAddExpense={() => {}} />}
          {activeTab === 'history' && <HistoryView transactions={transactions} expenses={expenses} />}
        </main>
      </div>

      {isAIOpen && <AIAssistant onClose={() => setIsAIOpen(false)} products={products} transactions={transactions} />}

      {isReceiptOpen && lastTransaction && (
