                <input type="text" value={formData.image} onChange={e => setFormData({...formData, image: e.target.value})} placeholder="https://..." className="w-full px-4 py-2.5 bg-slate-800 border border-white/5 rounded-xl text-white text-xs outline-none"/>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[8px] font-black text-slate-500 uppercase">Price</label>
                  <input type="number" value={formData.price} onChange={e => setFormData({...formData, price: parseInt(e.target.value)})} className="w-full px-4 py-2.5 bg-slate-800 border border-white/5 rounded-xl text-white text-xs font-black outline-none"/>
                </div>
                <div className="space-y-1">
                  <label className="text-[8px] font-black text-slate-500 uppercase">Stock</label>
                  <input type="number" value={formData.stock} onChange={e => setFormData({...formData, stock: parseInt(e.target.value)})} className="w-full px-4 py-2.5 bg-slate-800 border border-white/5 rounded-xl text-white text-xs font-black outline-none"/>
                </div>
              </div>
            </div>
            <div className="mt-8 flex gap-3">
              <button onClick={() => setIsAdding(false)} className="flex-1 py-3 bg-slate-800 text-slate-500 font-black rounded-xl text-[9px] uppercase tracking-widest">Cancel</button>
              <button onClick={handleSave} className="flex-1 py-3 gradient-dark-green text-white font-black rounded-xl text-[9px] uppercase tracking-widest shadow-glow-green">Save</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

