                  className="w-full py-6 gradient-dark-green text-white rounded-[2rem] font-black text-sm shadow-glow-green uppercase tracking-[0.3em] active:scale-95 transition-all"
                >
                  Konfirmasi Lunas
                </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Product, CartItem, Category, PaymentMethod } from '../types';
import { TAX_RATE } from '../constants';

interface POSViewProps {
  products: Product[];
  cart: CartItem[];
  onAddToCart: (product: Product) => void;
  onRemoveFromCart: (productId: string) => void;
  onUpdateQuantity: (productId: string, delta: number) => void;
  onCheckout: (paymentMethod: PaymentMethod, amountPaid: number, discount: number, customerName: string) => void;
  barcodeInputRef: React.RefObject<HTMLInputElement | null>;
  onBarcodeSubmit: (code: string) => boolean;
}

export const POSView: React.FC<POSViewProps> = ({ 
  products, cart, onAddToCart, onRemoveFromCart, onUpdateQuantity, onCheckout, barcodeInputRef, onBarcodeSubmit 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState<Category | 'All'>('All');
  const [showCheckout, setShowCheckout] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [amountPaid, setAmountPaid] = useState('');

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const tax = subtotal * TAX_RATE;
  const total = Math.round(subtotal + tax);

  const filtered = products.filter(p => {
    const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.barcode.includes(searchTerm);
    const matchCat = activeCategory === 'All' || p.category === activeCategory;
    return matchSearch && matchCat;
  });

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      const success = onBarcodeSubmit(searchTerm);
      if (success) {
        setSearchTerm(''); 
      }
    }
  };

  const handleConfirmPayment = () => {
    const paid = parseFloat(amountPaid) || total;
    onCheckout(paymentMethod, paid, 0, '');
    setShowCheckout(false);
    setAmountPaid('');
  };

  return (
    <div className="flex h-full gap-6">
