              onKeyDown={handleKeyDown}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-12 pr-6 py-3.5 bg-slate-900 border border-white/10 rounded-2xl outline-none focus:border-orange-500/50 transition-all text-white text-sm font-semibold shadow-inner"
            />
          </div>

          <div className="flex gap-2 p-1 bg-slate-900/50 rounded-xl border border-white/5 overflow-x-auto no-scrollbar">
            <button 
              onClick={() => setActiveCategory('All')} 
              className={`px-5 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${activeCategory === 'All' ? 'bg-orange-600 text-white shadow-glow-orange' : 'text-slate-500 hover:text-slate-300'}`}
            >
