        </div>
      </div>

      {/* ULTRA COMPACT CHECKOUT MODAL WITH REAL-TIME CHANGE CALCULATION */}
      {showCheckout && (
        <div className="fixed inset-0 bg-black/85 backdrop-blur-md z-[200] flex items-center justify-center p-4 no-print animate-in fade-in duration-200">
