                >
                  {c}
                </button>
              ))}
            </div>

            <button 
              onClick={() => setShowPromoModal(true)}
              className="px-6 py-3 rounded-xl bg-purple-600/20 border border-purple-500/30 text-purple-400 font-black text-[9px] uppercase tracking-widest hover:bg-purple-600 hover:text-white transition-all shadow-lg flex items-center gap-2"
            >
              <span>🎁</span> Promo
            </button>
          </div>
        </div>

        {/* Grid 3 Kolom */}
        <div className="flex-1 overflow-y-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5 pr-2 pb-10 custom-scrollbar">
          {filtered.map(p => (
            <button 
              key={p.id}
              onClick={() => onAddToCart(p)}
              disabled={p.stock <= 0}
              className="obsidian-card group flex flex-col h-[360px] rounded-[2rem] p-5 text-left border border-white/5 hover:border-orange-500/50 transition-all duration-500 bg-slate-900/40 relative overflow-hidden shadow-lg"
            >
              <div className="absolute top-4 right-4 z-10">
                <span className={`text-[9px] font-black px-3 py-1 rounded-full shadow-lg ${p.stock < 10 ? 'bg-orange-600 text-white' : 'bg-slate-950/80 text-emerald-500 border border-emerald-500/30'}`}>
                   Stok: {p.stock}
                </span>
              </div>

              <div className="mb-4 h-40 w-full bg-slate-800 rounded-2xl overflow-hidden border border-white/5 flex items-center justify-center relative shrink-0">
                {p.image ? (
                  <img src={p.image} alt={p.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                ) : (
                  <span className="text-4xl opacity-20">📦</span>
                )}
                <div className="absolute inset-0 bg-gradient-to-t from-slate-950/60 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
              </div>

              <div className="flex flex-col flex-1 justify-between">
                <div>
                  <span className="text-[8px] font-black text-emerald-500/80 uppercase tracking-widest mb-1 block">{p.category}</span>
                  <h3 className="font-extrabold text-white text-sm leading-tight line-clamp-2 uppercase tracking-tight">
                    {p.name}
                  </h3>
                </div>

                <div className="flex justify-between items-end pt-2">
                  <div className="flex flex-col">
                    <span className="text-[8px] font-mono text-slate-500 mb-0.5">{p.barcode}</span>
                    <span className="text-xl font-black text-white tracking-tighter">
                      <span className="text-xs text-emerald-500 mr-0.5">Rp</span>
                      {p.price.toLocaleString()}
                    </span>
                  </div>
                  <div className="w-10 h-10 rounded-xl bg-white/5 border border-white/10 flex items-center justify-center text-slate-400 group-hover:bg-orange-600 group-hover:text-white transition-all text-lg font-black">
                    +
                  </div>
                </div>
              </div>

              {p.stock <= 0 && (
                <div className="absolute inset-0 bg-slate-950/90 backdrop-blur-md flex items-center justify-center z-20">
                  <div className="px-5 py-2 border-2 border-orange-600 text-orange-600 rounded-xl font-black uppercase text-[10px] tracking-widest rotate-[-12deg]">
                    HABIS
                  </div>
                </div>
              )}
            </button>
          ))}
        </div>
      </div>

      {/* RIGHT: Keranjang */}
      <div className="w-80 bg-slate-900/90 border border-white/10 rounded-[2rem] flex flex-col overflow-hidden shadow-2xl backdrop-blur-md shrink-0">
        <div className="p-6 border-b border-white/5 flex items-center justify-between bg-slate-950/40">
          <h3 className="text-[10px] font-black text-white uppercase tracking-[0.2em]">Keranjang</h3>
          <span className="text-[9px] font-black px-3 py-1 bg-orange-600 rounded-full text-white">{cart.length}</span>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-10">
              <span className="text-5xl mb-3">🛒</span>
              <p className="text-[9px] font-black uppercase">Kosong</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex gap-3 items-center bg-white/5 p-3 rounded-2xl border border-white/5 group transition-all">
                 <div className="w-10 h-10 rounded-lg overflow-hidden shrink-0 border border-white/5">
                    <img src={item.image} className="w-full h-full object-cover" />
                 </div>
                 <div className="flex-1 min-w-0">
                    <h4 className="text-[10px] font-bold text-slate-100 truncate uppercase">{item.name}</h4>
                    <p className="text-[10px] text-emerald-500 font-black">Rp {item.price.toLocaleString()}</p>
                 </div>
                 <div className="flex items-center gap-1.5 bg-slate-950/60 p-1 rounded-lg">
                    <button onClick={() => onUpdateQuantity(item.id, -1)} className="w-5 h-5 rounded-md bg-slate-800 flex items-center justify-center text-slate-400">-</button>
                    <span className="text-[10px] font-black w-4 text-center">{item.quantity}</span>
                    <button onClick={() => onUpdateQuantity(item.id, 1)} className="w-5 h-5 rounded-md bg-slate-800 flex items-center justify-center text-slate-400">+</button>
                 </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-slate-950/60 border-t border-white/5 space-y-3">
          <div className="flex justify-between text-[10px] font-black text-slate-500 uppercase tracking-widest">
            <span>Subtotal</span>
            <span className="text-slate-300">Rp {subtotal.toLocaleString()}</span>
          </div>
          {activeDiscount > 0 && (
            <div className="flex justify-between text-[10px] font-black text-purple-400 uppercase tracking-widest">
              <span>Diskon Promo</span>
              <span>- Rp {activeDiscount.toLocaleString()}</span>
            </div>
          )}
          <div className="pt-3 border-t border-white/10">
            <p className="text-[9px] font-black text-emerald-500 uppercase tracking-widest mb-1">Grand Total</p>
            <p className="text-3xl font-black text-white tracking-tighter">Rp {total.toLocaleString()}</p>
          </div>
          <button 
            disabled={cart.length === 0}
            onClick={() => setShowCheckout(true)}
            className="w-full py-4 gradient-dark-orange text-white rounded-2xl font-black text-[11px] shadow-glow-orange uppercase tracking-[0.2em] transition-all"
          >
            BAYAR SEKARANG
          </button>
        </div>
      </div>

      {/* PROMO MANAGEMENT MODAL */}
