                <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest block text-center">Pilih Nominal Diskon</label>
                <div className="grid grid-cols-3 gap-3">
                  {[5000, 10000, 20000, 50000].map(val => (
                    <button 
                      key={val}
                      onClick={() => { setActiveDiscount(val); setShowPromoModal(false); }}
                      className="py-3 bg-slate-800 border border-white/5 rounded-xl text-white font-black text-[10px] hover:bg-purple-600 hover:border-purple-500 transition-all"
                    >
                      {val/1000}K
                    </button>
                  ))}
                  <button 
                    onClick={() => { setActiveDiscount(0); setShowPromoModal(false); }}
                    className="col-span-2 py-3 bg-rose-600/20 border border-rose-500/30 text-rose-500 font-black text-[10px] rounded-xl hover:bg-rose-600 hover:text-white transition-all"
                  >
                    RESET DISKON
                  </button>
                </div>
              </div>

              <div className="h-[1px] bg-white/5"></div>

              {/* Promo Code Input */}
              <div className="space-y-3">
                <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest block text-center">Masukkan Kode Promo</label>
                <div className="flex gap-2">
                  <input 
                    type="text" 
                    placeholder="Contoh: HEMAT10"
                    value={promoCode}
                    onChange={(e) => setPromoCode(e.target.value)}
                    className="flex-1 bg-slate-800 border border-white/5 rounded-xl px-4 py-3 text-sm text-white font-bold outline-none focus:border-purple-500/50"
                  />
                  <button 
                    onClick={handleApplyPromo}
                    className="bg-purple-600 text-white px-4 rounded-xl font-black text-[10px] uppercase shadow-lg shadow-purple-900/20"
                  >
                    Cek
                  </button>
                </div>
                <p className="text-[8px] text-slate-500 italic text-center uppercase">Info: Coba kode 'HEMAT10' atau 'MAZIYYAH'</p>
              </div>

              {/* Manual Discount */}
              <div className="space-y-3 pt-4 border-t border-white/5">
                 <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest block text-center">Input Diskon Manual (Rp)</label>
                 <input 
                    type="number" 
                    placeholder="0"
                    value={activeDiscount}
                    onChange={(e) => setActiveDiscount(parseInt(e.target.value) || 0)}
                    className="w-full bg-slate-950 border border-white/10 rounded-xl px-4 py-4 text-center text-xl font-black text-emerald-500 outline-none"
                 />
              </div>

              <button 
                onClick={() => setShowPromoModal(false)}
                className="w-full py-4 bg-white text-slate-900 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl active:scale-95 transition-all"
              >
                Simpan & Terapkan
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ULTRA COMPACT CHECKOUT MODAL WITH REAL-TIME CHANGE CALCULATION */}
      {showCheckout && (
        <div className="fixed inset-0 bg-black/85 backdrop-blur-md z-[200] flex items-center justify-center p-4 no-print animate-in fade-in duration-200">
           <div className="bg-slate-900 rounded-[2rem] shadow-2xl p-6 w-full max-w-[320px] border border-white/10 animate-in zoom-in duration-300">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-[11px] font-black text-white uppercase tracking-widest">Pembayaran</h3>
                <button onClick={() => setShowCheckout(false)} className="w-8 h-8 flex items-center justify-center rounded-xl bg-slate-800 text-slate-500 hover:text-white transition-all">✕</button>
              </div>

              <div className="space-y-4">
                {/* Method Selector */}
                <div className="grid grid-cols-2 gap-2">
                   {Object.values(PaymentMethod).map(m => (
                     <button 
                      key={m} 
                      onClick={() => setPaymentMethod(m)}
                      className={`py-3 px-1 rounded-xl border transition-all flex flex-col items-center gap-1 ${paymentMethod === m ? 'border-orange-500 bg-orange-500/10 text-orange-500 shadow-glow-orange' : 'border-white/5 bg-slate-800/40 text-slate-500 hover:bg-slate-800'}`}
                     >
                        <span className="text-xl">{m === PaymentMethod.CASH ? '💵' : m === PaymentMethod.QRIS ? '📱' : m === PaymentMethod.DEBIT ? '💳' : '👛'}</span>
                        <span className="text-[8px] font-black uppercase tracking-tight">{m}</span>
                     </button>
                   ))}
                </div>

                {/* Bill Amount */}
                <div className="p-3 bg-slate-950/60 rounded-2xl border border-white/5 text-center">
                   <p className="text-[8px] font-black text-slate-500 uppercase mb-1">Total Tagihan</p>
                   {activeDiscount > 0 && (
                     <p className="text-[9px] font-bold text-rose-500 line-through">Rp {totalBeforeDiscount.toLocaleString()}</p>
                   )}
                   <p className="text-2xl font-black text-white tracking-tighter">Rp {total.toLocaleString()}</p>
                </div>

                {paymentMethod === PaymentMethod.CASH && (
                  <div className="space-y-3">
                    <div className="space-y-1">
                      <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest block text-center">Uang Tunai</label>
                      <input 
                        type="number" 
                        placeholder="Input Rp..."
                        value={amountPaid}
                        autoFocus
                        onChange={(e) => setAmountPaid(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && isAmountEnough && handleConfirmPayment()}
                        className="w-full py-4 bg-slate-800 border-2 border-white/5 rounded-2xl text-center text-2xl font-black text-white outline-none focus:border-orange-500/50"
                      />
                    </div>

                    {/* REAL-TIME CHANGE DISPLAY */}
                    <div className={`p-4 rounded-2xl border transition-all ${isAmountEnough ? 'bg-emerald-500/10 border-emerald-500/20' : 'bg-rose-500/10 border-rose-500/20'}`}>
                      <div className="flex justify-between items-center mb-1">
                        <span className="text-[9px] font-black uppercase text-slate-500">
                          {isAmountEnough ? 'KEMBALIAN' : 'KURANG'}
                        </span>
                        <span className={`text-[10px] font-black ${isAmountEnough ? 'text-emerald-500' : 'text-rose-500'}`}>
                          {isAmountEnough ? '✓ CUKUP' : '⚠ KURANG'}
                        </span>
                      </div>
                      <p className={`text-2xl font-black tracking-tighter text-center ${isAmountEnough ? 'text-emerald-500' : 'text-rose-500'}`}>
                        Rp {Math.abs(changeAmount).toLocaleString()}
                      </p>
                    </div>
                  </div>
                )}

                <button 
                  onClick={handleConfirmPayment}
                  disabled={paymentMethod === PaymentMethod.CASH && !isAmountEnough}
                  className={`w-full py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] transition-all ${isAmountEnough || paymentMethod !== PaymentMethod.CASH ? 'gradient-dark-green text-white shadow-glow-green active:scale-95' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}
                >
                  Konfirmasi Lunas
                </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Product, Category } from '../types';

interface InventoryViewProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  onAddExpense: (description: string, amount: number, category: string) => void;
}

export const InventoryView: React.FC<InventoryViewProps> = ({ products, setProducts, onAddExpense }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    barcode: '',
    category: Category.FOOD,
    price: 0,
    costPrice: 0,
    stock: 0,
    image: ''
  });

  const handleSave = () => {
    if (!formData.name || !formData.barcode || !formData.price) {
      alert("Mohon lengkapi Nama, Barcode, dan Harga Jual!");
      return;
    }

    if (editingId) {
      setProducts(prev => prev.map(p => p.id === editingId ? { ...p, ...formData } as Product : p));
      setEditingId(null);
    } else {
      const newProduct = { 
        ...formData, 
        id: Date.now().toString(),
        costPrice: formData.costPrice || Math.round((formData.price || 0) * 0.8) // Default cost price if not set
      } as Product;
      setProducts(prev => [...prev, newProduct]);
      setIsAdding(false);
    }
    resetForm();
  };

  const resetForm = () => {
    setFormData({ name: '', barcode: '', category: Category.FOOD, price: 0, costPrice: 0, stock: 0, image: '' });
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        alert("Ukuran file terlalu besar! Maksimal 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, image: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="h-full flex flex-col gap-6 animate-in fade-in duration-500">
      <div className="flex justify-between items-end px-2">
        <div>
          <h2 className="text-2xl font-black text-white tracking-tight uppercase">Inventory Control</h2>
          <p className="text-emerald-500 text-[8px] font-black uppercase tracking-[0.4em] mt-1">Terminal Stock Monitoring</p>
        </div>
        <button 
          onClick={() => { resetForm(); setIsAdding(true); setEditingId(null); }}
          className="gradient-dark-green text-white px-6 py-3 rounded-xl font-black shadow-glow-green hover:brightness-110 active:scale-95 transition-all text-[9px] uppercase tracking-widest"
        >
          Tambah Produk Baru
        </button>
      </div>

      <div className="flex-1 overflow-auto rounded-[2.5rem] bg-slate-900/50 border border-white/5 custom-scrollbar shadow-2xl">
        <table className="w-full text-left border-collapse">
          <thead className="bg-slate-950/80 sticky top-0 border-b border-white/5 z-10 backdrop-blur-md">
            <tr>
              <th className="p-6 font-black text-slate-500 uppercase text-[8px] tracking-[0.3em]">Visual</th>
              <th className="p-6 font-black text-slate-500 uppercase text-[8px] tracking-[0.3em]">Item Details</th>
              <th className="p-6 font-black text-slate-500 uppercase text-[8px] tracking-[0.3em]">Category</th>
              <th className="p-6 font-black text-slate-500 uppercase text-[8px] tracking-[0.3em]">Price (Sell/Cost)</th>
              <th className="p-6 font-black text-slate-500 uppercase text-[8px] tracking-[0.3em]">Stock</th>
              <th className="p-6 font-black text-slate-500 uppercase text-[8px] tracking-[0.3em] text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5">
            {products.map(product => (
              <tr key={product.id} className="hover:bg-white/5 transition-all group">
                <td className="p-6">
                   <div className="w-12 h-12 rounded-xl overflow-hidden border border-white/10 bg-slate-800 flex items-center justify-center">
                      {product.image ? (
                        <img src={product.image} className="w-full h-full object-cover" />
                      ) : (
                        <span className="text-xl opacity-20">📦</span>
                      )}
                   </div>
                </td>
                <td className="p-6">
