                  <button onClick={() => { if(confirm('Hapus produk ini?')) setProducts(p => p.filter(x => x.id !== product.id))}} className="text-slate-600 hover:text-rose-500 text-[9px] font-black uppercase tracking-widest">Hapus</button>
