      setActiveDiscount(50000);
      setIsPromoUnlocked(true);
      alert('Kode Promo Berhasil! Diskon Rp 50.000 Aktif.');
    } else if (code === 'MASTER') {
       setIsPromoUnlocked(true);
       alert('Mode Promo Terbuka! Silakan masukkan diskon manual.');
