                        <span className="text-xl">{m === PaymentMethod.CASH ? '💵' : m === PaymentMethod.QRIS ? '📱' : m === PaymentMethod.DEBIT ? '💳' : '👛'}</span>
                        <span className="text-[8px] font-black uppercase tracking-tight">{m}</span>
                     </button>
                   ))}
                </div>

                <div className="p-3 bg-slate-950/60 rounded-2xl border border-white/5 text-center">
                   <p className="text-[8px] font-black text-slate-500 uppercase mb-1">Total Tagihan</p>
                   <p className="text-2xl font-black text-white tracking-tighter">Rp {total.toLocaleString()}</p>
                </div>

                {paymentMethod === PaymentMethod.CASH && (
                  <div className="space-y-3">
                    <input 
                      type="number" 
                      placeholder="Input Uang Tunai..."
                      value={amountPaid}
                      autoFocus
                      onChange={(e) => setAmountPaid(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && isAmountEnough && handleConfirmPayment()}
                      className="w-full py-4 bg-slate-800 border-2 border-white/5 rounded-2xl text-center text-2xl font-black text-white outline-none focus:border-orange-500/50"
                    />
                    <div className={`p-4 rounded-2xl border transition-all ${isAmountEnough ? 'bg-emerald-500/10 border-emerald-500/20' : 'bg-rose-500/10 border-rose-500/20'}`}>
                      <p className={`text-2xl font-black tracking-tighter text-center ${isAmountEnough ? 'text-emerald-500' : 'text-rose-500'}`}>
                        Rp {Math.abs(changeAmount).toLocaleString()}
                      </p>
                    </div>
                  </div>
                )}

                <button onClick={handleConfirmPayment} disabled={paymentMethod === PaymentMethod.CASH && !isAmountEnough} className={`w-full py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] transition-all ${isAmountEnough || paymentMethod !== PaymentMethod.CASH ? 'gradient-dark-green text-white shadow-glow-green active:scale-95' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}>LUNASKAN PESANAN</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Transaction, Product, Expense, Category } from '../types';

interface DashboardViewProps {
  transactions: Transaction[];
  products: Product[];
  expenses: Expense[];
  onNavigateToPos: () => void;
  onNavigateToInventory: () => void;
}

export const DashboardView: React.FC<DashboardViewProps> = ({ transactions, products, expenses, onNavigateToPos, onNavigateToInventory }) => {
  const [hoveredCat, setHoveredCat] = useState<string | null>(null);

  const totalRevenue = transactions.reduce((a, b) => a + b.total, 0);
  const totalCost = transactions.reduce((a, b) => a + b.totalCost, 0);
  const totalExpenses = expenses.reduce((a, b) => a + b.amount, 0);
  const netProfit = totalRevenue - totalCost - totalExpenses;

  const lowStockProducts = products.filter(p => p.stock > 0 && p.stock < 10);
  const outOfStockProducts = products.filter(p => p.stock <= 0);

  // Perhitungan persentase untuk breakdown margin
  const cogsPercent = totalRevenue > 0 ? (totalCost / totalRevenue) * 100 : 0;
  const expensePercent = totalRevenue > 0 ? (totalExpenses / totalRevenue) * 100 : 0;
  const profitPercent = totalRevenue > 0 ? (netProfit / totalRevenue) * 100 : 0;

  // Logic untuk Diagram Bundar (Composition per Category)
  const categoryData = Object.values(Category).map(cat => {
    let revenue = 0;
    transactions.forEach(t => {
      t.items.forEach(item => {
        if (item.category === cat) {
          revenue += (item.price * item.quantity);
        }
      });
    });
    return { name: cat, value: revenue };
  });

  const totalCatRevenue = categoryData.reduce((a, b) => a + b.value, 0) || 1;

  const getCategoryColor = (cat: string) => {
    switch (cat) {
      case Category.KITCHEN: return '#f97316'; // orange
      case Category.SCHOOL: return '#3b82f6'; // blue
      case Category.HOUSEHOLD: return '#a855f7'; // purple
      case Category.FOOD: return '#10b981'; // emerald
      case Category.BEVERAGE: return '#f59e0b'; // amber
      default: return '#64748b';
    }
  };

  const getCategoryTailwindColor = (cat: string) => {
    switch (cat) {
      case Category.KITCHEN: return 'bg-orange-500';
      case Category.SCHOOL: return 'bg-blue-500';
      case Category.HOUSEHOLD: return 'bg-purple-500';
      case Category.FOOD: return 'bg-emerald-500';
      case Category.BEVERAGE: return 'bg-amber-500';
      default: return 'bg-slate-500';
    }
  };

  // SVG Donut Logic
  let cumulativePercent = 0;
  const donutSlices = categoryData.map(d => {
    const percent = (d.value / totalCatRevenue) * 100;
    const startPercent = cumulativePercent;
    cumulativePercent += percent;
    return { ...d, startPercent, percent };
  });

  return (
    <div className="h-full flex flex-col space-y-8 animate-in fade-in duration-700">
      {/* Welcome Banner */}
      <div className="obsidian-card p-12 rounded-[3rem] bg-gradient-to-b from-slate-900 to-slate-950 border border-white/5 relative overflow-hidden group flex flex-col items-center justify-center text-center min-h-[300px]">
        <div className="absolute inset-0 opacity-5 pointer-events-none flex items-center justify-center">
          <span className="text-[280px] select-none">🏪</span>
        </div>

        <div className="relative z-10 flex flex-col items-center">
          <div className="w-16 h-16 rounded-2xl bg-orange-500/10 border border-orange-500/20 flex items-center justify-center text-3xl mb-6 shadow-glow-orange animate-bounce duration-[3000ms]">
            👋
          </div>
          <h1 className="text-4xl md:text-5xl font-black text-white tracking-tighter mb-4">
            Halo, Kasir <span className="text-orange-500">Anam</span>
          </h1>
          <p className="text-slate-400 text-base md:text-lg max-w-2xl mx-auto leading-relaxed font-medium">
            Selamat datang kembali di pusat kendali <span className="text-white font-bold">Maziyyah Mart</span>. 
            Sistem telah merangkum performa toko Anda hari ini dengan akurasi tinggi.
          </p>

          <div className="mt-10 flex flex-wrap gap-4 justify-center">
            <button onClick={onNavigateToPos} className="px-8 py-4 gradient-dark-orange text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-glow-orange hover:scale-105 active:scale-95 transition-all">
              🚀 Terminal Kasir
            </button>
            <button onClick={onNavigateToInventory} className="px-8 py-4 bg-slate-800/80 backdrop-blur-md text-slate-300 rounded-2xl font-black text-xs uppercase tracking-[0.2em] border border-white/10 hover:bg-slate-700 hover:text-white transition-all">
              📦 Cek Inventori
            </button>
          </div>
        </div>
      </div>

      {/* Main Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: 'Pendapatan Hari Ini', value: `Rp ${totalRevenue.toLocaleString()}`, icon: '💰', color: 'text-emerald-500', bg: 'bg-emerald-500/10' },
          { label: 'Estimasi Laba Bersih', value: `Rp ${netProfit.toLocaleString()}`, icon: '📈', color: 'text-blue-500', bg: 'bg-blue-500/10' },
          { label: 'Total Transaksi', value: transactions.length, icon: '🛒', color: 'text-orange-500', bg: 'bg-orange-500/10' },
          { label: 'Stok Habis', value: outOfStockProducts.length, icon: '⚠️', color: 'text-rose-500', bg: 'bg-rose-500/10' },
        ].map((stat, i) => (
          <div key={i} className="obsidian-card p-6 rounded-[2rem] flex items-center gap-5 border border-white/5">
            <div className={`w-14 h-14 rounded-2xl ${stat.bg} ${stat.color} flex items-center justify-center text-2xl shadow-inner`}>
              {stat.icon}
            </div>
            <div>
              <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest">{stat.label}</p>
              <p className="text-xl font-black text-white mt-1">{stat.value}</p>
            </div>
          </div>
        ))}
      </div>

      {/* COMPOSITION ANALYTICS: Interactive Donut Chart */}
      <div className="obsidian-card p-10 rounded-[2.5rem] bg-slate-900/50 border border-white/5 shadow-2xl relative overflow-hidden">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-12 gap-6 relative z-10">
          <div>
            <h3 className="text-xs font-black text-white uppercase tracking-widest">Komposisi Penjualan Kategori</h3>
            <p className="text-[10px] text-slate-500 font-bold uppercase mt-1">Distribusi Pendapatan Berdasarkan Jenis Barang</p>
          </div>
          <div className="bg-slate-950/40 px-4 py-2 rounded-xl border border-white/5 text-[9px] font-black text-orange-500 uppercase tracking-widest">
            Total Intel: Rp {totalCatRevenue.toLocaleString()}
          </div>
        </div>

        <div className="flex flex-col lg:flex-row items-center justify-around gap-12 relative z-10">
          {/* Donut Container */}
          <div className="relative w-64 h-64 md:w-80 md:h-80 flex items-center justify-center">
             <svg viewBox="0 0 42 42" className="w-full h-full transform -rotate-90">
                {donutSlices.map((slice, i) => (
                  <circle
                    key={i}
                    cx="21" cy="21" r="15.91549430918954"
                    fill="transparent"
                    stroke={getCategoryColor(slice.name)}
                    strokeWidth="4"
                    strokeDasharray={`${slice.percent} ${100 - slice.percent}`}
                    strokeDashoffset={-slice.startPercent}
                    className="transition-all duration-1000 ease-out cursor-pointer hover:stroke-white"
                    onMouseEnter={() => setHoveredCat(slice.name)}
                    onMouseLeave={() => setHoveredCat(null)}
                    style={{
                      filter: hoveredCat === slice.name ? `drop-shadow(0 0 8px ${getCategoryColor(slice.name)})` : 'none',
                      opacity: hoveredCat && hoveredCat !== slice.name ? 0.3 : 1
                    }}
                  />
                ))}
             </svg>

             {/* Center Text */}
             <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                {hoveredCat ? (
                  <>
                    <p className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">{hoveredCat}</p>
                    <p className="text-2xl font-black text-white tracking-tighter">
                      {((donutSlices.find(s => s.name === hoveredCat)?.percent || 0)).toFixed(1)}%
                    </p>
                  </>
                ) : (
                  <>
                    <span className="text-4xl mb-1">🛍️</span>
                    <p className="text-[8px] font-black text-slate-500 uppercase tracking-[0.2em]">Sales Mix</p>
                  </>
                )}
             </div>
          </div>

          {/* Legend Grid */}
          <div className="flex-1 grid grid-cols-1 sm:grid-cols-2 gap-4 w-full">
            {donutSlices.map((slice, i) => (
              <div 
                key={i} 
                onMouseEnter={() => setHoveredCat(slice.name)}
                onMouseLeave={() => setHoveredCat(null)}
                className={`p-5 rounded-3xl border transition-all duration-300 flex items-center justify-between ${hoveredCat === slice.name ? 'bg-white/10 border-white/20 scale-105' : 'bg-slate-950/20 border-white/5'}`}
              >
                <div className="flex items-center gap-4">
                   <div className={`w-3 h-3 rounded-full ${getCategoryTailwindColor(slice.name)} shadow-lg`}></div>
                   <div>
                      <p className="text-[10px] font-black text-white uppercase tracking-tight">{slice.name}</p>
                      <p className="text-[12px] font-black text-slate-500 mt-0.5">Rp {slice.value.toLocaleString()}</p>
                   </div>
                </div>
                <div className="text-right">
                   <span className="text-xs font-black text-white">{slice.percent.toFixed(1)}%</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Bottom Content: Alerts and Breakdown */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 pb-10">

        {/* Financial Breakdown Card */}
        <div className="lg:col-span-2 obsidian-card p-8 rounded-[2.5rem] bg-slate-900/50 border border-white/5 shadow-2xl">
          <div className="flex justify-between items-center mb-8">
            <div>
              <h3 className="text-xs font-black text-white uppercase tracking-widest">Alokasi Margin Bisnis</h3>
              <p className="text-[10px] text-slate-500 font-bold uppercase mt-1">Efisiensi Pendapatan Terhadap Pengeluaran</p>
            </div>
            <div className="text-right">
              <p className="text-[8px] font-black text-slate-500 uppercase">Grand Total Revenue</p>
              <p className="text-lg font-black text-white leading-none">Rp {totalRevenue.toLocaleString()}</p>
            </div>
          </div>

          <div className="space-y-6">
            <div className="w-full h-8 flex rounded-2xl overflow-hidden border border-white/5 shadow-inner bg-slate-950">
              <div style={{ width: `${Math.max(1, cogsPercent)}%` }} className="h-full bg-orange-600 shadow-[inset_-4px_0_10px_rgba(0,0,0,0.3)] transition-all duration-1000"></div>
              <div style={{ width: `${Math.max(1, expensePercent)}%` }} className="h-full bg-rose-600 shadow-[inset_-4px_0_10px_rgba(0,0,0,0.3)] transition-all duration-1000"></div>
              <div style={{ width: `${Math.max(1, profitPercent)}%` }} className="h-full gradient-dark-green shadow-glow-green transition-all duration-1000"></div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div className="flex items-center gap-3">
                <div className="w-3 h-3 rounded-full bg-orange-600"></div>
                <div>
                  <p className="text-[8px] font-black text-slate-500 uppercase tracking-tighter">Modal (COGS)</p>
                  <p className="text-[11px] font-black text-white">Rp {totalCost.toLocaleString()} <span className="text-orange-500 ml-1">({cogsPercent.toFixed(1)}%)</span></p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <div className="w-3 h-3 rounded-full bg-rose-600"></div>
                <div>
                  <p className="text-[8px] font-black text-slate-500 uppercase tracking-tighter">Operasional</p>
                  <p className="text-[11px] font-black text-white">Rp {totalExpenses.toLocaleString()} <span className="text-rose-500 ml-1">({expensePercent.toFixed(1)}%)</span></p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <div className="w-3 h-3 rounded-full bg-emerald-500 shadow-glow-green"></div>
                <div>
                  <p className="text-[8px] font-black text-slate-500 uppercase tracking-tighter">Laba Bersih</p>
                  <p className="text-[11px] font-black text-emerald-500">Rp {netProfit.toLocaleString()} <span className="ml-1">({profitPercent.toFixed(1)}%)</span></p>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Stock Alerts Column */}
        <div className="lg:col-span-1 space-y-6">
          <div className="obsidian-card p-8 rounded-[2.5rem] bg-slate-900/50 border border-white/5 h-full">
            <div className="flex justify-between items-center mb-6">
               <h3 className="text-xs font-black text-white uppercase tracking-widest">Peringatan Stok</h3>
               <span className="text-[10px] font-black px-2 py-0.5 bg-rose-500/20 text-rose-500 rounded-md">Penting</span>
            </div>

            <div className="space-y-4 max-h-[400px] overflow-y-auto no-scrollbar pr-2">
               {lowStockProducts.length === 0 && outOfStockProducts.length === 0 ? (
                 <div className="text-center py-10 opacity-20">
                    <span className="text-4xl">✅</span>
                    <p className="text-[10px] font-black mt-2 uppercase">Stok Aman</p>
                 </div>
               ) : (
                 <>
                   {outOfStockProducts.map(p => (
                     <div key={p.id} className="p-4 bg-rose-500/5 border border-rose-500/20 rounded-2xl flex items-center justify-between">
                        <div>
                           <p className="text-[11px] font-black text-white uppercase">{p.name}</p>
                           <p className="text-[9px] text-rose-500 font-bold mt-0.5">STOK HABIS</p>
                        </div>
                        <span className="text-xl">🚫</span>
                     </div>
                   ))}
                   {lowStockProducts.map(p => (
                     <div key={p.id} className="p-4 bg-orange-500/5 border border-orange-500/20 rounded-2xl flex items-center justify-between">
                        <div>
                           <p className="text-[11px] font-black text-white uppercase">{p.name}</p>
                           <p className="text-[9px] text-orange-500 font-bold mt-0.5">Sisa: {p.stock} unit</p>
                        </div>
                        <span className="text-xl">⏳</span>
                     </div>
                   ))}
                 </>
               )}
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Transaction, Product, Expense, Category } from '../types';

interface DashboardViewProps {
  transactions: Transaction[];
  products: Product[];
  expenses: Expense[];
  onNavigateToPos: () => void;
  onNavigateToInventory: () => void;
}

export const DashboardView: React.FC<DashboardViewProps> = ({ transactions, products, expenses, onNavigateToPos, onNavigateToInventory }) => {
  const [hoveredCat, setHoveredCat] = useState<string | null>(null);
  const [hoveredDay, setHoveredDay] = useState<number | null>(null);

  const totalRevenue = transactions.reduce((a, b) => a + b.total, 0);
  const totalCost = transactions.reduce((a, b) => a + b.totalCost, 0);
  const totalExpenses = expenses.reduce((a, b) => a + b.amount, 0);
  const netProfit = totalRevenue - totalCost - totalExpenses;

  const lowStockProducts = products.filter(p => p.stock > 0 && p.stock < 10);
  const outOfStockProducts = products.filter(p => p.stock <= 0);

  // Perhitungan Keuangan
  const cogsPercent = totalRevenue > 0 ? (totalCost / totalRevenue) * 100 : 0;
  const expensePercent = totalRevenue > 0 ? (totalExpenses / totalRevenue) * 100 : 0;
  const profitPercent = totalRevenue > 0 ? (netProfit / totalRevenue) * 100 : 0;

  // Logic 7 Hari Terakhir
  const last7Days = [...Array(7)].map((_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - (6 - i));
    d.setHours(0, 0, 0, 0);
    return d;
  });

  const dailyRevenueData = last7Days.map(date => {
    const total = transactions
      .filter(t => new Date(t.timestamp).toDateString() === date.toDateString())
      .reduce((acc, t) => acc + t.total, 0);
    return {
      label: date.toLocaleDateString('id-ID', { weekday: 'short', day: 'numeric' }),
      value: total
    };
  });

  const maxRevenue = Math.max(...dailyRevenueData.map(d => d.value), 100000);

  // Logic Composition per Category (Donut Chart)
  const categoryData = Object.values(Category).map(cat => {
    let revenue = 0;
    transactions.forEach(t => {
      t.items.forEach(item => {
        if (item.category === cat) {
          revenue += (item.price * item.quantity);
        }
      });
    });
    return { name: cat, value: revenue };
  });

  const totalCatRevenue = categoryData.reduce((a, b) => a + b.value, 0) || 1;

  const getCategoryColor = (cat: string) => {
    switch (cat) {
      case Category.KITCHEN: return '#f97316';
      case Category.SCHOOL: return '#3b82f6';
      case Category.HOUSEHOLD: return '#a855f7';
      case Category.FOOD: return '#10b981';
      case Category.BEVERAGE: return '#f59e0b';
      default: return '#64748b';
    }
  };

  const getCategoryTailwindColor = (cat: string) => {
    switch (cat) {
      case Category.KITCHEN: return 'bg-orange-500';
      case Category.SCHOOL: return 'bg-blue-500';
      case Category.HOUSEHOLD: return 'bg-purple-500';
      case Category.FOOD: return 'bg-emerald-500';
      case Category.BEVERAGE: return 'bg-amber-500';
      default: return 'bg-slate-500';
    }
  };

  let cumulativePercent = 0;
  const donutSlices = categoryData.map(d => {
    const percent = (d.value / totalCatRevenue) * 100;
    const startPercent = cumulativePercent;
    cumulativePercent += percent;
    return { ...d, startPercent, percent };
  });

  return (
    <div className="h-full flex flex-col space-y-8 animate-in fade-in duration-700">
      {/* Welcome Banner */}
      <div className="obsidian-card p-10 rounded-[3rem] bg-gradient-to-b from-slate-900 to-slate-950 border border-white/5 relative overflow-hidden group flex flex-col items-center justify-center text-center min-h-[280px]">
        <div className="absolute inset-0 opacity-5 pointer-events-none flex items-center justify-center">
          <span className="text-[280px] select-none">🏪</span>
        </div>
        <div className="relative z-10">
          <div className="w-14 h-14 rounded-2xl bg-orange-500/10 border border-orange-500/20 flex items-center justify-center text-2xl mx-auto mb-6 shadow-glow-orange">👋</div>
          <h1 className="text-3xl md:text-4xl font-black text-white tracking-tighter mb-4">Halo, Kasir <span className="text-orange-500">Anam</span></h1>
          <p className="text-slate-400 text-sm md:text-base max-w-xl mx-auto leading-relaxed font-medium">Monitoring performa toko <span className="text-white font-bold">Maziyyah Mart</span> Anda hari ini.</p>
          <div className="mt-8 flex flex-wrap gap-4 justify-center">
            <button onClick={onNavigateToPos} className="px-8 py-3.5 gradient-dark-orange text-white rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] shadow-glow-orange hover:scale-105 transition-all">🚀 Terminal Kasir</button>
            <button onClick={onNavigateToInventory} className="px-8 py-3.5 bg-slate-800/80 backdrop-blur-md text-slate-300 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] border border-white/10 hover:bg-slate-700 transition-all">📦 Cek Inventori</button>
          </div>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: 'Pendapatan Hari Ini', value: `Rp ${totalRevenue.toLocaleString()}`, icon: '💰', color: 'text-emerald-500', bg: 'bg-emerald-500/10' },
          { label: 'Estimasi Laba Bersih', value: `Rp ${netProfit.toLocaleString()}`, icon: '📈', color: 'text-blue-500', bg: 'bg-blue-500/10' },
          { label: 'Total Transaksi', value: transactions.length, icon: '🛒', color: 'text-orange-500', bg: 'bg-orange-500/10' },
          { label: 'Stok Habis', value: outOfStockProducts.length, icon: '⚠️', color: 'text-rose-500', bg: 'bg-rose-500/10' },
        ].map((stat, i) => (
          <div key={i} className="obsidian-card p-6 rounded-[2rem] flex items-center gap-4 border border-white/5">
            <div className={`w-12 h-12 rounded-xl ${stat.bg} ${stat.color} flex items-center justify-center text-xl shadow-inner`}>{stat.icon}</div>
            <div>
              <p className="text-[8px] font-black text-slate-500 uppercase tracking-widest">{stat.label}</p>
              <p className="text-lg font-black text-white mt-1">{stat.value}</p>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* NEW: 7-Day Revenue Trend Bar Chart */}
        <div className="obsidian-card p-10 rounded-[2.5rem] bg-slate-900/50 border border-white/5 shadow-2xl relative overflow-hidden">
          <div className="flex justify-between items-center mb-10">
            <div>
              <h3 className="text-xs font-black text-white uppercase tracking-widest">Tren Pendapatan 7 Hari</h3>
              <p className="text-[10px] text-slate-500 font-bold uppercase mt-1">Sumbu Y: Rupiah | Sumbu X: Tanggal</p>
            </div>
            <div className="px-3 py-1 bg-emerald-500/10 text-emerald-500 text-[8px] font-black rounded-lg border border-emerald-500/20 uppercase tracking-widest">Live Report</div>
          </div>

          <div className="h-64 flex items-end justify-between gap-3 px-2 relative border-l border-b border-white/10 pb-2">
            {/* Scale Helper Lines */}
            <div className="absolute left-0 right-0 top-0 bottom-0 pointer-events-none flex flex-col justify-between opacity-5">
              <div className="w-full h-[1px] bg-white"></div>
              <div className="w-full h-[1px] bg-white"></div>
              <div className="w-full h-[1px] bg-white"></div>
              <div className="w-full h-[1px] bg-white"></div>
            </div>

            {dailyRevenueData.map((day, idx) => (
              <div 
                key={idx} 
                className="flex-1 flex flex-col items-center group relative h-full justify-end"
                onMouseEnter={() => setHoveredDay(idx)}
                onMouseLeave={() => setHoveredDay(null)}
              >
                {/* Tooltip */}
                <div className={`absolute -top-16 bg-slate-800 border border-white/10 p-3 rounded-2xl shadow-2xl z-20 pointer-events-none min-w-[120px] transition-all duration-300 ${hoveredDay === idx ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
                   <p className="text-[8px] font-black text-slate-500 uppercase mb-1">{day.label}</p>
                   <p className="text-sm font-black text-emerald-500">Rp {day.value.toLocaleString()}</p>
                </div>

                <div 
                  className={`w-full max-w-[40px] rounded-t-xl transition-all duration-700 relative overflow-hidden ${hoveredDay === idx ? 'bg-emerald-400 shadow-glow-green brightness-125' : 'bg-emerald-600'}`}
                  style={{ height: `${(day.value / maxRevenue) * 100}%`, minHeight: '4px' }}
                >
                  <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent"></div>
                </div>
                <span className="text-[8px] font-black text-slate-500 mt-4 uppercase tracking-tighter whitespace-nowrap">{day.label}</span>
              </div>
            ))}
          </div>

          {/* Y-Axis Label */}
          <div className="absolute left-4 top-1/2 -translate-y-1/2 -rotate-90 origin-left text-[8px] font-black text-slate-600 uppercase tracking-[0.5em] pointer-events-none">
            Rupiah Trend
          </div>
        </div>

        {/* Composition Analytics (Donut Chart) */}
        <div className="obsidian-card p-10 rounded-[2.5rem] bg-slate-900/50 border border-white/5 shadow-2xl">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-xs font-black text-white uppercase tracking-widest">Komposisi Penjualan</h3>
            <span className="text-[9px] font-black text-orange-500">Sales Mix</span>
          </div>

          <div className="flex flex-col sm:flex-row items-center justify-around gap-8">
            <div className="relative w-48 h-48 shrink-0">
               <svg viewBox="0 0 42 42" className="w-full h-full transform -rotate-90">
                  {donutSlices.map((slice, i) => (
                    <circle
                      key={i}
                      cx="21" cy="21" r="15.91549430918954"
                      fill="transparent"
                      stroke={getCategoryColor(slice.name)}
                      strokeWidth="5"
                      strokeDasharray={`${slice.percent} ${100 - slice.percent}`}
                      strokeDashoffset={-slice.startPercent}
                      className="transition-all duration-1000 cursor-pointer hover:stroke-white"
                      onMouseEnter={() => setHoveredCat(slice.name)}
                      onMouseLeave={() => setHoveredCat(null)}
                      style={{ opacity: hoveredCat && hoveredCat !== slice.name ? 0.3 : 1 }}
                    />
                  ))}
               </svg>
               <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                  <p className="text-xl font-black text-white">{hoveredCat ? `${donutSlices.find(s => s.name === hoveredCat)?.percent.toFixed(1)}%` : '🛍️'}</p>
                  <p className="text-[7px] font-black text-slate-500 uppercase tracking-widest">{hoveredCat || 'Kategori'}</p>
               </div>
            </div>

            <div className="flex-1 grid grid-cols-1 gap-2 w-full">
              {donutSlices.map((slice, i) => (
                <div key={i} className={`p-3 rounded-xl flex items-center justify-between border transition-all ${hoveredCat === slice.name ? 'bg-white/5 border-white/20' : 'bg-slate-950/20 border-white/5'}`}>
                   <div className="flex items-center gap-3">
                      <div className={`w-2 h-2 rounded-full ${getCategoryTailwindColor(slice.name)} shadow-lg`}></div>
                      <span className="text-[9px] font-black text-white uppercase truncate max-w-[100px]">{slice.name}</span>
                   </div>
                   <span className="text-[9px] font-black text-slate-400">{slice.percent.toFixed(1)}%</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Financial Breakdown & Alerts */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 pb-10">
        <div className="lg:col-span-2 obsidian-card p-8 rounded-[2.5rem] bg-slate-900/50 border border-white/5">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-xs font-black text-white uppercase tracking-widest">Alokasi Margin Bisnis</h3>
            <p className="text-lg font-black text-white">Rp {totalRevenue.toLocaleString()}</p>
          </div>
          <div className="space-y-6">
            <div className="w-full h-6 flex rounded-xl overflow-hidden bg-slate-950">
              <div style={{ width: `${Math.max(1, cogsPercent)}%` }} className="h-full bg-orange-600 transition-all duration-1000"></div>
              <div style={{ width: `${Math.max(1, expensePercent)}%` }} className="h-full bg-rose-600 transition-all duration-1000"></div>
              <div style={{ width: `${Math.max(1, profitPercent)}%` }} className="h-full gradient-dark-green transition-all duration-1000"></div>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div className="flex items-center gap-3">
                <div className="w-2.5 h-2.5 rounded-full bg-orange-600"></div>
                <div>
                  <p className="text-[7px] font-black text-slate-500 uppercase">Modal (COGS)</p>
                  <p className="text-[10px] font-black text-white">{cogsPercent.toFixed(1)}%</p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <div className="w-2.5 h-2.5 rounded-full bg-rose-600"></div>
                <div>
                  <p className="text-[7px] font-black text-slate-500 uppercase">Operasional</p>
                  <p className="text-[10px] font-black text-white">{expensePercent.toFixed(1)}%</p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <div className="w-2.5 h-2.5 rounded-full bg-emerald-500 shadow-glow-green"></div>
                <div>
                  <p className="text-[7px] font-black text-slate-500 uppercase">Laba Bersih</p>
                  <p className="text-[10px] font-black text-emerald-500">{profitPercent.toFixed(1)}%</p>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="lg:col-span-1 obsidian-card p-8 rounded-[2.5rem] bg-slate-900/50 border border-white/5">
          <h3 className="text-xs font-black text-white uppercase tracking-widest mb-6">Stok Alert</h3>
          <div className="space-y-3 max-h-[300px] overflow-y-auto no-scrollbar">
             {lowStockProducts.length === 0 && outOfStockProducts.length === 0 ? (
               <p className="text-[10px] text-slate-600 text-center py-10 uppercase font-black">Semua Stok Aman ✅</p>
             ) : (
               <>
                 {outOfStockProducts.map(p => (
                   <div key={p.id} className="p-3 bg-rose-500/5 border border-rose-500/20 rounded-xl flex items-center justify-between">
                      <span className="text-[10px] font-black text-white uppercase truncate max-w-[120px]">{p.name}</span>
                      <span className="text-[8px] font-black text-rose-500 uppercase">Habis</span>
                   </div>
                 ))}
                 {lowStockProducts.map(p => (
                   <div key={p.id} className="p-3 bg-orange-500/5 border border-orange-500/20 rounded-xl flex items-center justify-between">
                      <span className="text-[10px] font-black text-white uppercase truncate max-w-[120px]">{p.name}</span>
                      <span className="text-[8px] font-black text-orange-500 uppercase">Menipis</span>
                   </div>
                 ))}
               </>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Product, CartItem, Category, Transaction, PaymentMethod, Expense } from './types';
import { INITIAL_PRODUCTS, TAX_RATE } from './constants';
import { DashboardView } from './components/DashboardView';
import { POSView } from './components/POSView';
import { InventoryView } from './components/InventoryView';
import { HistoryView } from './components/HistoryView';
import { Receipt } from './components/Receipt';
import { AIAssistant } from './components/AIAssistant';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'pos' | 'inventory' | 'history'>('dashboard');
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);
  const [isAIOpen, setIsAIOpen] = useState(false);

  const barcodeInputRef = useRef<HTMLInputElement>(null);

  const handleAddToCart = (product: Product) => {
    if (product.stock <= 0) return;
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) return prev;
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const handleBarcodeSubmit = (code: string) => {
    const product = products.find(p => p.barcode === code);
    if (product) {
      handleAddToCart(product);
      return true;
    }
    return false;
  };

  const handleAddExpense = (description: string, amount: number, category: string) => {
    const newExpense: Expense = {
      id: `EXP-${Date.now()}`,
      timestamp: new Date(),
      description,
      amount,
      category
    };
    setExpenses(prev => [newExpense, ...prev]);
  };

  const handleCheckout = (paymentMethod: PaymentMethod, amountPaid: number, discount: number = 0, customerName: string = '') => {
    const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const totalCost = cart.reduce((acc, item) => acc + (item.costPrice * item.quantity), 0);
    const tax = subtotal * TAX_RATE;
    const total = Math.round(subtotal + tax - discount);
    const change = amountPaid - total;

    const newTransaction: Transaction = {
      id: `TRX-${Date.now()}`,
      timestamp: new Date(),
      items: [...cart],
      subtotal,
      tax,
      discount,
      total,
      totalCost,
      paymentMethod,
      amountPaid,
      change,
      customerName
    };

    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(ci => ci.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    setTransactions(prev => [newTransaction, ...prev]);
    setLastTransaction(newTransaction);
    setCart([]);
    setIsReceiptOpen(true);
  };

  return (
    <div className="flex h-screen overflow-hidden bg-[#020617] text-slate-200">
      {/* Sidebar */}
      <aside className="w-20 md:w-56 glass-dark flex flex-col z-30 no-print">
        <div className="h-20 flex items-center px-6">
          <div className="w-10 h-10 gradient-dark-orange rounded-xl flex items-center justify-center shadow-glow-orange shrink-0">
            <span className="text-white font-black text-xl">M</span>
          </div>
          <div className="ml-3 hidden md:block overflow-hidden">
            <h1 className="font-extrabold text-white text-sm leading-none truncate">Maziyyah Mart</h1>
            <p className="text-[8px] text-emerald-500 font-black uppercase tracking-widest mt-1">PRO System</p>
          </div>
        </div>

        <nav className="flex-1 px-3 space-y-2 mt-8">
          {[
            { id: 'dashboard', icon: '🏠', label: 'Dashboard', color: 'text-purple-500', bg: 'bg-purple-500/10' },
            { id: 'pos', icon: '🛒', label: 'Kasir', color: 'text-orange-500', bg: 'bg-orange-500/10' },
            { id: 'inventory', icon: '📦', label: 'Stok', color: 'text-emerald-500', bg: 'bg-emerald-500/10' },
            { id: 'history', icon: '📊', label: 'Laporan', color: 'text-blue-500', bg: 'bg-blue-500/10' },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full group flex items-center p-3.5 rounded-xl transition-all ${activeTab === item.id ? `${item.bg} ${item.color} border border-white/5 shadow-glow-orange` : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}
            >
              <span className="text-lg">{item.icon}</span>
              <span className="ml-3 hidden md:block font-bold text-[10px] uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-4">
          <button 
            onClick={() => setIsAIOpen(true)}
            className="w-full bg-slate-800/50 border border-white/5 text-white p-3 rounded-xl flex items-center justify-center gap-2 hover:bg-slate-700 transition-all"
          >
            <span className="text-base">✨</span>
            <span className="hidden md:block font-extrabold text-[9px] uppercase tracking-widest text-orange-400">Tanya AI</span>
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-20 flex items-center justify-between px-8 no-print border-b border-white/5 bg-slate-950/20">
          <div className="flex items-center gap-4">
            <h2 className="text-xl font-black text-white capitalize tracking-tight">
              {activeTab === 'dashboard' ? 'Overview Bisnis' : activeTab === 'pos' ? 'Terminal Kasir' : activeTab === 'inventory' ? 'Inventori & Stok' : 'Laporan Bisnis'}
            </h2>
            <div className="h-4 w-[1px] bg-white/10"></div>
            <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">System Active</span>
          </div>

          <div className="flex items-center gap-8">
            <div className="text-right hidden sm:block">
              <p className="text-[8px] font-black text-emerald-500 uppercase tracking-widest">Revenue Today</p>
              <p className="font-black text-white text-lg leading-tight">Rp {transactions.reduce((a, b) => a + b.total, 0).toLocaleString()}</p>
            </div>
            <div className="flex items-center gap-2.5 bg-slate-900/50 px-3 py-1.5 rounded-xl border border-white/5">
               <div className="w-7 h-7 rounded-lg gradient-dark-orange flex items-center justify-center text-white text-[10px] font-bold">A</div>
               <div className="hidden lg:block text-left">
                  <p className="text-[8px] font-black text-slate-500 uppercase leading-none">Login As</p>
                  <p className="text-[10px] font-bold text-slate-300 mt-0.5">Anam (Kasir)</p>
               </div>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-auto p-6 bg-[#020617]">
          {activeTab === 'dashboard' && (
            <DashboardView 
              transactions={transactions} 
              products={products} 
              expenses={expenses}
              onNavigateToPos={() => setActiveTab('pos')}
              onNavigateToInventory={() => setActiveTab('inventory')}
            />
          )}
          {activeTab === 'pos' && (
            <POSView 
              products={products}
              cart={cart}
              onAddToCart={handleAddToCart}
              onRemoveFromCart={(id) => setCart(prev => prev.filter(i => i.id !== id))}
              onUpdateQuantity={(id, d) => setCart(prev => prev.map(i => i.id === id ? {...i, quantity: Math.max(1, i.quantity + d)} : i))}
              onCheckout={handleCheckout}
              barcodeInputRef={barcodeInputRef}
              onBarcodeSubmit={handleBarcodeSubmit}
            />
          )}
          {activeTab === 'inventory' && (
            <InventoryView 
              products={products} 
              setProducts={setProducts} 
              onAddExpense={handleAddExpense} 
            />
          )}
          {activeTab === 'history' && (
            <HistoryView 
              transactions={transactions} 
              expenses={expenses} 
              onAddExpense={(e) => setExpenses(prev => [e, ...prev])} 
            />
          )}
        </main>
      </div>

      {isAIOpen && <AIAssistant onClose={() => setIsAIOpen(false)} products={products} transactions={transactions} />}

      {isReceiptOpen && lastTransaction && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-md flex items-center justify-center z-[100] p-4 no-print">
           <div className="bg-white rounded-[2.5rem] p-8 max-w-sm w-full shadow-2xl animate-in zoom-in duration-300">
              <div className="max-h-[70vh] overflow-y-auto no-scrollbar">
                <Receipt transaction={lastTransaction} />
              </div>
              <div className="mt-8 flex gap-3">
                 <button onClick={() => window.print()} className="flex-1 bg-emerald-600 text-white font-black py-4 rounded-2xl shadow-lg hover:brightness-110 transition-all text-xs uppercase tracking-widest">Cetak Struk</button>
                 <button onClick={() => setIsReceiptOpen(false)} className="flex-1 bg-slate-100 text-slate-500 font-black py-4 rounded-2xl hover:bg-slate-200 transition-all text-xs uppercase tracking-widest">Tutup</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Product, Category } from '../types';

interface InventoryViewProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  onAddExpense: (description: string, amount: number, category: string) => void;
}

export const InventoryView: React.FC<InventoryViewProps> = ({ products, setProducts, onAddExpense }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const [restockProduct, setRestockProduct] = useState<Product | null>(null);
  const [restockAmount, setRestockAmount] = useState<number>(0);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    barcode: '',
    category: Category.FOOD,
    price: 0,
    costPrice: 0,
    stock: 0,
    image: ''
  });

  const handleSave = () => {
    if (!formData.name || !formData.barcode || !formData.price) {
      alert("Mohon lengkapi Nama, Barcode, dan Harga Jual!");
      return;
    }

    if (editingId) {
      setProducts(prev => prev.map(p => p.id === editingId ? { ...p, ...formData } as Product : p));
      setEditingId(null);
    } else {
      const newProduct = { 
        ...formData, 
        id: Date.now().toString(),
        costPrice: formData.costPrice || Math.round((formData.price || 0) * 0.8)
      } as Product;
      setProducts(prev => [...prev, newProduct]);
      setIsAdding(false);
    }
    resetForm();
  };

  const resetForm = () => {
    setFormData({ name: '', barcode: '', category: Category.FOOD, price: 0, costPrice: 0, stock: 0, image: '' });
  };

  const handleRestock = () => {
    if (!restockProduct || restockAmount <= 0) return;

    const totalCost = restockAmount * restockProduct.costPrice;

    // 1. Update stok produk
    setProducts(prev => prev.map(p => 
      p.id === restockProduct.id ? { ...p, stock: p.stock + restockAmount } : p
    ));

    // 2. Catat sebagai pengeluaran (mempengaruhi laba bersih)
    onAddExpense(
      `Restok: ${restockProduct.name} (${restockAmount} unit)`, 
      totalCost, 
      'Pengadaan Barang'
    );

    setRestockProduct(null);
    setRestockAmount(0);
    alert(`Stok berhasil ditambah! Biaya Rp ${totalCost.toLocaleString()} dicatat sebagai pengeluaran.`);
